/* POSIX blockmarks (macOS): mirror Win32 tracker for post-intro hang diagnosis. */
typedef struct { unsigned long tid; const char* what; unsigned long long arg;
                 unsigned long long since_ms; char name[24]; } ppu_blockmark_posix_t;
#define PPU_BLOCKMARK_POSIX_MAX 64
static ppu_blockmark_posix_t g_blockmarks_posix[PPU_BLOCKMARK_POSIX_MAX];
static unsigned long long ps3_now_ms_bm(void) {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return (unsigned long long)ts.tv_sec * 1000ull + (unsigned long long)(ts.tv_nsec / 1000000ull);
}
extern "C" void ppu_blockmark_set(const char* what, unsigned long long arg) {
    unsigned long tid = ps3_host_tid();
    unsigned long long now = ps3_now_ms_bm();
    for (int i = 0; i < PPU_BLOCKMARK_POSIX_MAX; i++)
        if (g_blockmarks_posix[i].tid == tid) {
            g_blockmarks_posix[i].what = what; g_blockmarks_posix[i].arg = arg;
            g_blockmarks_posix[i].since_ms = now; return; }
    for (int i = 0; i < PPU_BLOCKMARK_POSIX_MAX; i++)
        if (g_blockmarks_posix[i].tid == 0) {
            g_blockmarks_posix[i].tid = tid; g_blockmarks_posix[i].what = what;
            g_blockmarks_posix[i].arg = arg; g_blockmarks_posix[i].since_ms = now; return; }
}
extern "C" void ppu_blockmark_clear(void) {
    unsigned long tid = ps3_host_tid();
    for (int i = 0; i < PPU_BLOCKMARK_POSIX_MAX; i++)
        if (g_blockmarks_posix[i].tid == tid) { g_blockmarks_posix[i].what = 0; return; }
}
extern "C" void ppu_blockmark_name(const char* name) {
    unsigned long tid = ps3_host_tid();
    /* Varias threads reclamam slots deste array de diagnostico ao mesmo tempo:
     * ler `tid` e escreve-lo em passos separados era data race (TSan) e podia
     * dar o mesmo slot a duas threads. A reclamacao passa a ser um CAS. */
    for (int i = 0; i < PPU_BLOCKMARK_POSIX_MAX; i++) {
        unsigned long cur = __atomic_load_n(&g_blockmarks_posix[i].tid, __ATOMIC_RELAXED);
        if (cur != tid) {
            unsigned long expect = 0;
            if (cur != 0 ||
                !__atomic_compare_exchange_n(&g_blockmarks_posix[i].tid, &expect, tid,
                                             0, __ATOMIC_ACQ_REL, __ATOMIC_RELAXED))
                continue;
        }
        strncpy(g_blockmarks_posix[i].name, name ? name : "?", 23);
        g_blockmarks_posix[i].name[23] = 0;
        return;
    }
}
extern "C" void ppu_blockmark_dump(void) {
    unsigned long long now = ps3_now_ms_bm();
    for (int i = 0; i < PPU_BLOCKMARK_POSIX_MAX; i++)
        if (g_blockmarks_posix[i].tid && g_blockmarks_posix[i].what)
            fprintf(stderr, "[BLOCK] tid=%lu name='%s' in %s(0x%llx) for %llums\n",
                    g_blockmarks_posix[i].tid, g_blockmarks_posix[i].name,
                    g_blockmarks_posix[i].what,
                    (unsigned long long)g_blockmarks_posix[i].arg,
                    now - g_blockmarks_posix[i].since_ms);
    fflush(stderr);
}

/* Priority acquire for woken waiters: MUST NOT run the prio backoff (they'd
 * wait for themselves). Ordinary hot paths see g_giant_prio_waiters and yield. */
extern "C" void ppu_giant_lock_acquire_prio(void)
{
    __sync_fetch_and_add(&g_giant_prio_waiters, 1);
    __sync_fetch_and_add(&g_giant_prio_waiters_fw, 1);
    ppu_giant_lock_acquire_raw();
    __sync_fetch_and_sub(&g_giant_prio_waiters_fw, 1);
    __sync_fetch_and_sub(&g_giant_prio_waiters, 1);
}

/* Called by known-hot re-acquire sites (sys_timer_usleep) before locking so
 * a crowd of just-woken waiters drains first. */
extern "C" void ppu_giant_lock_hot_backoff(void)
{
    /* E198 (2026-09-02): ate' aqui girava com o giant lock NA MAO enquanto havia prio-waiters
     * -- que precisavam exactamente desse lock. Agora larga-o, cede a CPU enquanto houver
     * waiters (cap 100 yields) e volta a pedi-lo. So' faz sentido chamado com o lock detido
     * (sys_timer_usleep depois de readquirir; sys_tty_write). */
    if (GIANT_LD(g_giant_prio_waiters) <= 0 && GIANT_LD(g_giant_waiters) <= 0) return;
    if (GIANT_LD(g_giant_holder_tid) != (long)GetCurrentThreadId()) return;
    ppu_giant_lock_release();
    int n = 0;
    while ((GIANT_LD(g_giant_prio_waiters) > 0 || GIANT_LD(g_giant_waiters) > 0) && n++ < 100) Sleep(0);
    ppu_giant_lock_acquire();
}

