#include "ppu_store32_be.h"
/* Same functional steps as vm_fast(5): oob, type15, uncommitted, tblsize, BE store, rsv.
 * Lift TUs can call this directly (ppu_vm_write_hot.h) without the diagnostic tail. */
extern "C" void vm_write32_hot(uint64_t a, uint32_t v)
{
    if (vm_oob((uint32_t)a, 4)) {
        ps3_mem_oob_report((uint32_t)a, 4, "write", __builtin_return_address(0));
        return;
    }
    if (ps3_type15_block_stomp((uint32_t)a, v))
        return;
    if (vm_uncommitted_guard((uint32_t)a, 4, "write32", __builtin_return_address(0)))
        return;
    if (tblsize_guard((uint32_t)a, v, __builtin_return_address(0)))
        return;
    ps3_store32_be(vm_base, (uint32_t)a, v);
    ppu_rsv_on_store((uint32_t)a, 4);
}
extern "C" void vm_write64_hot(uint64_t a, uint64_t v)
{
    if (vm_oob((uint32_t)a, 8)) {
        ps3_mem_oob_report((uint32_t)a, 8, "write", __builtin_return_address(0));
        return;
    }
    if (vm_uncommitted_guard((uint32_t)a, 8, "write64", __builtin_return_address(0)))
        return;
    if (tblsize_guard((uint32_t)a, v, __builtin_return_address(0)))
        return;
    ps3_store64_be(vm_base, (uint32_t)a, v);
    ppu_rsv_on_store((uint32_t)a, 8);
}
