#if defined(__APPLE__)
/* ---------------------------------------------------------------------------
 * PS3_TRACE_HOST_STACK -- env-gated (OFF by default), read-only host-stack
 * high-water probe. It does NOT change any guest state or control flow: it only
 * reads the host thread's own stack geometry.
 *
 * Why it exists (Task 5 of the macos-movie-eos plan): the "~1/4 SIGBUS after
 * recursion cap @0x0045CB90" was diagnosed as a HOST stack overflow on the PPU
 * main thread (~8 KB/frame x 4000 frames ~= 32 MB, blowing -Wl,-stack_size).
 * This probe REFUTES that. Reproduce the recursion with PS3_BCTR_HOSTCALL=1
 * (restores the legacy bctr=host-call so the intro's never-converging
 * snd_stream audio-open poll -- movie obj 0x008697D8, guest state at the cap
 * lr=0 r3=r4=0x84010002 -- stacks a host frame per iteration up to the cap) and
 * the probe measures per_level ~= 514 B and only ~2 MB used at depth 4000, with
 * ~62 MB headroom on a 64 MB stack. The depth-4000 cap can never overflow even
 * the 32 MB stack: bumping -Wl,-stack_size is NOT the fix. The real SIGBUS is
 * the cap's skip returning a corrupt result (r3 stays 0x84010002, an EA in the
 * inaccessible guest gap) that the caller then dereferences; the committed
 * bctr-tail fix already keeps that poll from reaching the cap (it becomes an
 * O(1) DRAIN_TRAMPOLINE loop), so in the default build the crash does not
 * reproduce. Kept as reusable instrumentation for any future "is this a host
 * stack overflow?" question -- answer it by measurement, not by guessing.
 *
 * macOS-only (uses the Darwin pthread stack accessors); the Windows build never
 * compiles this and is unaffected.
 * -----------------------------------------------------------------------*/
static int ppu_host_stack_probe_on(void)
{
    static int on = -1;
    if (on < 0) {
        const char* v = getenv("PS3_TRACE_HOST_STACK");
        on = (v && v[0] && v[0] != '0') ? 1 : 0;
    }
    return on;
}
static void ppu_host_stack_sample(const char* where, int depth)
{
    pthread_t self = pthread_self();
    char* top = (char*)pthread_get_stackaddr_np(self);   /* high end of stack */
    size_t sz  = pthread_get_stacksize_np(self);
    char here;                                            /* current low mark */
    long used = (long)(top - &here);
    fprintf(stderr,
            "  [host-stack] %s depth=%d thread_stack=%.1fMB used=%.2fMB "
            "per_level=%ldB headroom=%.2fMB\n",
            where, depth, sz / 1048576.0, used / 1048576.0,
            depth > 0 ? used / (long)depth : 0L,
            ((long)sz - used) / 1048576.0);
    fflush(stderr);
}
#endif

/* Occupancy of RSX local memory (0xC0000000..). Discriminator for empty
 * TEX-PX: did ANY path (PPU store / DMA / transfer) fill VRAM, or only the
 * bind slots we sample stay zero? Gated PS3_TRACE_VRAM / PS3_TRACE_TEX_PIXELS.
 * Read-only; OFF by default. phase: 0=post-R_Perm, 1=mid-boot flip, 2=late. */
extern "C" void ps3_scan_vram_occupancy(int phase)
{
    static int on = -1;
    if (on < 0) {
        const char* e = getenv("PS3_TRACE_VRAM");
        const char* e2 = getenv("PS3_TRACE_TEX_PIXELS");
        on = ((e && e[0] && e[0] != '0') || (e2 && e2[0] && e2[0] != '0')) ? 1 : 0;
    }
    if (!on || !vm_base) return;

    /* Cap how many full scans we emit (cheap enough for a few). */
    static int nscan = 0;
    if (nscan >= 4) return;
    nscan++;

    const uint32_t base = 0xC0000000u;
    const uint32_t size = 0x10000000u; /* 256 MB announced by MapLocalMemory */
    const uint32_t slab = 0x100000u;   /* 1 MB */
    uint32_t hot_slabs = 0;
    uint64_t total_nz_est = 0;
    uint32_t first_hot = 0, first_hot_max = 0;

    fprintf(stderr, "[VRAM-SCAN] phase=%d base=0x%08X size=0x%X slab=1MB\n",
            phase, base, size);
    fflush(stderr);

    for (uint32_t off = 0; off < size; off += slab) {
        uint32_t ea = base + off;
        if (!ppu_guest_range_committed(ea, 256))
            continue;
        /* Stride sample: 1 byte every 256 → 4 KB / slab. */
        uint32_t nz = 0, mx = 0;
        const uint8_t* p = vm_base + ea;
        for (uint32_t i = 0; i < slab; i += 256) {
            uint8_t b = p[i];
            if (b) {
                nz++;
                if (b > mx) mx = b;
            }
        }
        if (nz) {
            hot_slabs++;
            total_nz_est += nz;
            if (!first_hot) {
                first_hot = ea;
                first_hot_max = mx;
            }
            if (hot_slabs <= 12) {
                fprintf(stderr,
                        "[VRAM-SCAN] hot slab ea=0x%08X sample_nz=%u/4096 max=%u\n",
                        ea, nz, mx);
            }
        }
    }

    /* Known HD bind slots (TEX-PX). Full DXT1 1280x720 = 460800 B. */
    static const uint32_t k_binds[] = {
        0xC0FB0980u, 0xC1021180u, 0xC0F40180u, 0
    };
    for (int i = 0; k_binds[i]; i++) {
        uint32_t ea = k_binds[i];
        if (!ppu_guest_range_committed(ea, 4096)) {
            fprintf(stderr, "[VRAM-SCAN] bind ea=0x%08X UNCOMMITTED\n", ea);
            continue;
        }
        const uint8_t* p = vm_base + ea;
        uint32_t nbytes = 460800u;
        uint32_t nz = 0, mx = 0;
        for (uint32_t j = 0; j < nbytes; j++) {
            if (p[j] > mx) mx = p[j];
            if (p[j]) nz++;
        }
        fprintf(stderr,
                "[VRAM-SCAN] bind ea=0x%08X dxt1_full nz=%u/%u max=%u\n",
                ea, nz, nbytes, mx);
    }

    /* HOSTRES scratch (inflate dst) — was 0x4B000000 for ctxr; may be reused. */
    {
        uint32_t ea = 0x4B000000u;
        if (ppu_guest_range_committed(ea, 512)) {
            const uint8_t* p = vm_base + ea;
            uint32_t nz = 0, mx = 0;
            for (uint32_t j = 0; j < 460928u; j++) {
                if (p[j] > mx) mx = p[j];
                if (p[j]) nz++;
            }
            fprintf(stderr,
                    "[VRAM-SCAN] hostres_scratch ea=0x%08X nz=%u/460928 max=%u "
                    "head=%02X%02X%02X%02X\n",
                    ea, nz, mx, p[0], p[1], p[2], p[3]);
        }
    }

    fprintf(stderr,
            "[VRAM-SCAN] done phase=%d hot_slabs=%u sample_nz_est=%llu "
            "first_hot=0x%08X max=%u (no GCM SetTransfer HLE in runtime)\n",
            phase, hot_slabs, (unsigned long long)total_nz_est,
            first_hot, first_hot_max);
    fflush(stderr);
}

/* After R_Perm: scan guest RAM for the micro-ctor factory OPD pointer
 * 0x00534CB8 (→ code 0x32854C). Static analysis found ZERO absolute/TOC-rel
 * materializations and ZERO bl to 0x32854C — if anything registers the factory
 * at runtime, the pointer appears in heap/data. Gated PS3_TRACE_MC / A1CHAIN.
 * Read-only; OFF by default. */
extern "C" void ps3_scan_mc_factory_opd(ppu_context* ctx)
{
    static int s_done = 0;
    if (!ctx || !g_ps3_rperma_full || s_done) return;
    static int on = -1;
    if (on < 0) {
        const char* e = getenv("PS3_TRACE_MC");
        const char* e2 = getenv("PS3_TRACE_A1CHAIN");
        on = ((e && e[0] && e[0] != '0') || (e2 && e2[0] && e2[0] != '0')) ? 1 : 0;
    }
    if (!on) return;
    s_done = 1;
    if (!vm_base) {
        fprintf(stderr, "[MC-SCAN] no vm_base\n");
        fflush(stderr);
        return;
    }
    const uint32_t needle_opd = 0x00534CB8u;
    const uint32_t needle_code = 0x0032854Cu;
    const uint32_t needle_opd2 = 0x00534D70u; /* 00329490 OPD */
    int hits = 0;
    /* Scan common guest windows (skip giant holes). */
    static const uint32_t ranges[][2] = {
        { 0x00100000u, 0x01000000u },
        { 0x10000000u, 0x18000000u },
        { 0x40000000u, 0x48000000u },
        { 0xC0000000u, 0xC2000000u },
        { 0, 0 },
    };
    fprintf(stderr, "[MC-SCAN] searching for OPD 0x%08X / code 0x%08X / OPD 0x%08X\n",
            needle_opd, needle_code, needle_opd2);
    fflush(stderr);
    for (int r = 0; ranges[r][0] || ranges[r][1]; r++) {
        uint32_t a0 = ranges[r][0], a1 = ranges[r][1];
        for (uint32_t a = a0; a + 4 < a1 && hits < 24; a += 4) {
            if (!ppu_guest_range_committed(a, 4)) {
                /* skip ahead a page-ish */
                a = (a & ~0xFFFu) + 0x1000u - 4u;
                continue;
            }
            /* Skip the .opd home itself (0x51xxxx–0x54xxxx holds code words). */
            if (a >= 0x00510000u && a < 0x00550000u)
                continue;
            uint32_t w = vm_read32(a);
            if (w == needle_opd || w == needle_code || w == needle_opd2) {
                fprintf(stderr, "[MC-SCAN] hit @0x%08X val=0x%08X\n", a, w);
                fflush(stderr);
                hits++;
            }
        }
    }
    fprintf(stderr, "[MC-SCAN] done hits=%d\n", hits);
    fflush(stderr);
}

/* Read-only dump of ICG component/typemap after R_Perm full.
 * H3 discriminator (2026-07-22): is the typemap object installed naturally?
 * Never calls OPD / never builds synthetic stream. Gated PS3_TRACE_TYMAP_DUMP
 * (fallback PS3_TRACE_A1CHAIN / PS3_TRACE_TYMAP). OFF by default. */
extern "C" void ps3_dump_post_wad_typemap(ppu_context* ctx)
{
    static int s_done = 0;
    static int s_fail_logs = 0;
    if (!ctx || !g_ps3_rperma_full || s_done) return;

    uint32_t toc = (uint32_t)ctx->gpr[2];
    if (!toc) {
        if (s_fail_logs++ < 4) {
            fprintf(stderr, "[TYMAP-DUMP] wait: TOC(r2)=0\n");
            fflush(stderr);
        }
        return;
    }
    uint32_t base = vm_read32(toc + (uint32_t)(-0x2584));
    uint32_t comp_slot = base ? (base + 0x130000u + 0x4980u) : 0;
    uint32_t component = comp_slot ? vm_read32(comp_slot) : 0;
    uint32_t typemap = component ? vm_read32(component + 0xDC) : 0;
    uint32_t vt = typemap ? vm_read32(typemap + 0) : 0;
    uint32_t slot8 = (vt == 0x005130B8u && typemap) ? vm_read32(vt + 0x8) : 0;

    /* Same fallback addresses as GATE-FORCE — only for comparison logging. */
    uint32_t fb_comp = 0, fb_tm = 0, fb_vt = 0;
    {
        static const uint32_t k_try[] = { 0x4306ADF0u, 0 };
        for (int i = 0; k_try[i]; i++) {
            uint32_t c = k_try[i];
            uint32_t tm = vm_read32(c + 0xDC);
            uint32_t tv = tm ? vm_read32(tm + 0) : 0;
            if (tm) {
                fb_comp = c;
                fb_tm = tm;
                fb_vt = tv;
                break;
            }
        }
    }

    s_done = 1;
    fprintf(stderr,
            "[TYMAP-DUMP] base=0x%08X slot=0x%08X comp=0x%08X tm=0x%08X vt=0x%08X "
            "vt+8=0x%08X fb_comp=0x%08X fb_tm=0x%08X fb_vt=0x%08X\n",
            base, comp_slot, component, typemap, vt, slot8,
            fb_comp, fb_tm, fb_vt);
    fflush(stderr);
}

