/* PS3_TRACE_ICALL_TO=0xEA[,0xEA...]: quem despacha para uma EA guest.
 *
 * Medido a 2026-08-01: neste lift nem o `lr` do guest nem o rbp frame walk
 * servem para atribuir uma chamada indirecta -- o `lr` fica preso no ultimo
 * `bl` e o frame walk, com trampolins e tail-calls, nao mapeia 1:1 nas
 * chamadas guest. O que resta e' apanhar o despacho no proprio ponto de
 * resolucao, com os registos de argumento e a cadeia host simbolizada.
 *
 * TEM DE ESTAR NOS DOIS DESPACHANTES. Enquanto so' esteve no
 * ps3_indirect_call, dava ZERO para func_00220F88 -- que corre de facto, pelo
 * caminho do `bctr` (ps3_indirect_tail, com o seu proprio ppu_lookup). Um
 * tracer que cobre metade dos caminhos mente por omissao, e a omissao parece
 * prova. O parametro `via` diz por qual dos dois passou.
 *
 * Ate 8 moradas. OFF por default: uma leitura de contador e um branch. */
static void ps3_trace_icall_to(uint32_t addr, ppu_context* ctx, const char* via)
{
    static int tn = -1; static uint32_t tea[8];
    if (tn < 0) { const char* s = getenv("PS3_TRACE_ICALL_TO"); tn = 0;
        while (s && *s && tn < 8) {
            while (*s == ' ' || *s == ',') s++;
            if (!*s) break;
            char* end = 0; unsigned long u = strtoul(s, &end, 0);
            if (end == s) break;
            tea[tn++] = (uint32_t)u; s = end;
        }
        if (tn > 0) { fprintf(stderr, "[ICALLTO] a vigiar %d alvo(s):", tn);
                      for (int i = 0; i < tn; i++) fprintf(stderr, " 0x%08X", tea[i]);
                      fprintf(stderr, "%c", 10); fflush(stderr); } }
    if (tn <= 0 || !ctx) return;
    for (int i = 0; i < tn; i++) { if (addr != tea[i]) continue;
        /* Cap configuravel por PS3_TRACE_ICALL_TO_CAP (default 64, <0 = sem
         * limite). Estava a 64 a martelo e enganou-me a 2026-08-01: 64 linhas
         * exactas fizeram-me concluir que NENHUM push ia para a fabrica
         * 0x400C6210, quando o watch do cursor mostrava 175 push/pop nela.
         * Era o cap. Quarta armadilha do mesmo genero no mesmo dia. */
        static int k = 0;
        static int kcap = -2;
        if (kcap == -2) { const char* e = getenv("PS3_TRACE_ICALL_TO_CAP");
            kcap = (e && *e) ? (int)strtol(e, 0, 0) : 64;
            if (kcap < 0) kcap = 0x7FFFFFFF; }
        if (k++ < kcap) {
            fprintf(stderr,
                    "[ICALLTO] via=%s -> 0x%08X  r3=0x%08X r4=0x%08X r5=0x%08X lr=0x%08X r12=0x%08X\n",
                    via, addr, (uint32_t)ctx->gpr[3], (uint32_t)ctx->gpr[4],
                    (uint32_t)ctx->gpr[5], (uint32_t)ctx->lr, (uint32_t)ctx->gpr[12]);
            void* ra[4] = { __builtin_return_address(0), __builtin_return_address(1),
                            __builtin_return_address(2), __builtin_return_address(3) };
            fprintf(stderr, "          host:");
            for (int j = 0; j < 4; j++) { Dl_info di;
                if (dladdr(ra[j], &di) && di.dli_sname)
                    fprintf(stderr, " %s+0x%lX", di.dli_sname,
                            (unsigned long)((const char*)ra[j] - (const char*)di.dli_saddr));
                else fprintf(stderr, " %p", ra[j]); }
            fprintf(stderr, "%c", 10); fflush(stderr);
        }
        break; }
}

