/* Valor devolvido em r3 pelos disjuntores ICALL-HEAP / ICALL-ASCII quando
 * saltam uma chamada indirecta com alvo invalido.
 *
 * DESCOBERTA 2026-08-08 (ledger E65): o `0` nao e' neutro. No sitio medido
 * (FUN_0014f6f8, um append a buffer) o guest faz
 *
 *     if (fim < cursor + 1) { if (vt[0](obj,1) != 0) return; }
 *     *cursor = ...; cursor++;
 *
 * ou seja, `0` quer dizer "cresceu com sucesso, continua a escrever". Com o
 * buffer cheio e o crescimento saltado, o guest escreve fora do fim e volta a
 * tentar -- o que produziu os >= 8192 / >= 4096 ciclos do E64. Devolver
 * nao-zero fa'-lo desistir do append.
 *
 * Default continua 0 (baseline inalterado). PS3_ICALL_SKIP_RET=N devolve N,
 * para medir a diferenca sem mudar o default. */
static uint32_t ps3_icall_skip_ret(void)
{
    static int v = -1;
    if (v < 0) {
        const char* e = getenv("PS3_ICALL_SKIP_RET");
        v = (e && *e) ? (int)strtol(e, 0, 0) : 0;
        if (v) fprintf(stderr, "[ICALL] skip devolve r3=%d (PS3_ICALL_SKIP_RET)\n", v);
    }
    return (uint32_t)v;
}
extern "C" void ps3_indirect_call(ppu_context* ctx)
{
    /* After full R_PermA, unlock type-map→ICGLdr once from any live guest call.
     * Opt-in: PS3_GATE_FORCE=1. Synthetic stream is a last-resort kick when the
     * natural type-dispatch never fires after the permanent WAD is fully read. */
    {
        static int gf = -1;
        if (gf < 0) {
            const char* v = getenv("PS3_GATE_FORCE");
            gf = (v && v[0] && v[0] != '0') ? 1 : 0;
        }
        if (gf && g_ps3_rperma_full)
            ps3_force_post_wad_icgldr(ctx);
    }
    /* H3: dump-only, no forge. */
    {
        static int dump = -1;
        if (dump < 0) {
            const char* v = getenv("PS3_TRACE_TYMAP_DUMP");
            const char* v2 = getenv("PS3_TRACE_A1CHAIN");
            const char* v3 = getenv("PS3_TRACE_TYMAP");
            dump = ((v && v[0] && v[0] != '0')
                    || (v2 && v2[0] && v2[0] != '0')
                    || (v3 && v3[0] && v3[0] != '0')) ? 1 : 0;
        }
        if (dump && g_ps3_rperma_full)
            ps3_dump_post_wad_typemap(ctx);
    }
    /* Micro-ctor factory OPD presence in guest RAM (schedule climb). */
    if (g_ps3_rperma_full)
        ps3_scan_mc_factory_opd(ctx);
    /* VRAM occupancy (empty TEX-PX discriminator). */
    if (g_ps3_rperma_full) {
        static int vdone = 0;
        if (!vdone) {
            vdone = 1;
            ps3_scan_vram_occupancy(0);
        }
    }

    uint32_t addr = (uint32_t)ctx->ctr;
    /* Null / return-to-OS sentinel: a bctr to address 0 means the guest
     * unwound to the initial frame (or a not-yet-populated function pointer).
     * Don't treat it as an unresolved call -- just return to the caller. */
    if (addr == 0)
        return;
    /* FIX (poisoned-vtable-slot, confirmed 2026-07-02): 0xC0DE1111 is a
     * deliberate "this virtual method is intentionally unimplemented"
     * placeholder the game's own vtables ship with (confirmed at one call
     * site via a register dump + a scoped fix there; a SECOND, different
     * call site hitting the exact same value proves this is a game-wide
     * convention, not a one-off). Left unhandled, dispatching through it
     * leaves the caller's gpr3 undefined, which cascades into whatever
     * garbage happens to be there being treated as a real chained result
     * (leading through more garbage addresses -- 0xC0DE1111 ->
     * 0x005165A0 -> ... -> 0xFF0000FF -- until the stuck-call guard below
     * aborts the whole process). Treat it like the addr==0 sentinel above
     * (don't attempt the call) but ALSO clear gpr3 to 0, matching the
     * "did this optional virtual call produce a result?" idiom every
     * confirmed caller of this pattern checks for. */
    if (addr == 0xC0DE1111u) { ctx->gpr[3] = 0; return; }
    /* Sentinela do callback de overflow do FIFO GCM (ver cellGcmSetupContext,
     * gate PS3_GCM_CB; ledger E66). O guest chama-o com r3 = &CellGcmContextData
     * quando `current` chega ao `end`. O contrato e': libertar espaco e devolver
     * CELL_OK, ou nao-zero para o guest desistir do append.
     * Sem RSX a consumir o FIFO, repor `current = begin` e' o equivalente ao
     * wrap que a consola faria depois do GET passar. */
    if (addr == 0x0A0C0DE0u) {
        wp60_ovf_words = (uint32_t)ctx->gpr[4];   /* winport v60-async-seg */
        ctx->gpr[3] = (uint32_t)ps3_gcm_ctx_overflow((uint32_t)ctx->gpr[3]);
        return;
    }
    /* Heap-as-code (post-B71 AUTO_LOAD): CTR lands in guest heap band
     * 0x20xxxxxx–0x3Fxxxxxx (observed 0x27182818 from junk product/OPD after
     * R_Perm). Not guest text — never resolve; clear r3 and return so stuck
     * guard does not FATAL-abort the run. */
    if (addr >= 0x20000000u && addr < 0x40000000u) {
        static unsigned long n = 0;
        ++n;
        /* O cap era `if (n++ < 16) fprintf(...)` -- no PRINT, nao no skip. O
         * disjuntor continuava a absorver despachos indefinidamente e o log
         * mostrava sempre 16, o que me levou a escrever "16 despachos" no
         * ledger E62 quando o numero real era desconhecido (corrigido no E63).
         * Um contador que se cala ao chegar ao limite mente exactamente como o
         * cap do watch que ja' custou uma leitura errada a 2026-08-01.
         * Agora: as primeiras 16 (detalhe) MAIS cada potencia de 2 (magnitude),
         * o que sobrevive a um kill -TERM porque nao depende de atexit. */
        if (n <= 16 || (n & (n - 1)) == 0)
            fprintf(stderr, "[ICALL-HEAP] skip #%lu ctr=0x%08X lr=0x%08X r3=0x%08X (heap-as-code)\n",
                    n, addr, (uint32_t)ctx->lr, (uint32_t)ctx->gpr[3]);
        ctx->gpr[3] = ps3_icall_skip_ret();
        return;
    }
    /* R2 Disc A / H3 (2026-07-23): high freelist heap-as-code 0x40xxxxxx
     * (observed ICALL-BAD ctr=0x40637488). Same skip semantics as ICALL-HEAP
     * (r3=0, no FATAL streak) but ONLY when PS3_ICALL_HEAP40=1.
     * Default OFF — not a permanent LIVE_SKIP / not a content fix.
     * Discriminates: if silencing 0x40-heap icalls restores SetFlip_after_R_Perm,
     * H3 is LIVE; timeline already suggests DEAD (flip dies before ICALL-BAD). */
    {
        static int heap40 = -1;
        if (heap40 < 0) {
            const char* v = getenv("PS3_ICALL_HEAP40");
            heap40 = (v && v[0] && v[0] != '0') ? 1 : 0;
            if (heap40)
                fprintf(stderr,
                        "[ICALL-HEAP40] enabled: skip ctr in [0x40000000,0x4F000000) "
                        "(opt-in disc; default OFF)\n");
        }
        if (heap40 && addr >= 0x40000000u && addr < 0x4F000000u) {
            static unsigned long n = 0;
            ++n;   /* mesma correccao dos irmaos acima (E63): cap era no print */
            if (n <= 16 || (n & (n - 1)) == 0)
                fprintf(stderr,
                        "[ICALL-HEAP40] skip #%lu ctr=0x%08X lr=0x%08X r3=0x%08X "
                        "(0x40-heap-as-code)\n",
                        n, addr, (uint32_t)ctx->lr, (uint32_t)ctx->gpr[3]);
            ctx->gpr[3] = 0;
            return;
        }
    }
    /* Path/string-as-code (F2B FO residual after GetPicture on re-Play):
     * CTR is 2–4 printable ASCII (e.g. 0x005F6D6F). Skip; if CE03C armed a
     * longjmp pad and StartSeq already >=2, abort Play host stack so thr can
     * run (StartSeq#2 was real — not PARK). Not a forge of StartSeq. */
    { if (ps3_icall_looks_like_ascii(addr) && !ppu_lookup(addr)) {
        static unsigned long n = 0;
        static uint32_t last_a = 0; static int streak = 0;
        ++n;   /* mesma correccao do ICALL-HEAP acima: o cap era no print */
        if (n <= 16 || (n & (n - 1)) == 0)
            fprintf(stderr, "[ICALL-ASCII] skip #%lu ctr=0x%08X lr=0x%08X r3=0x%08X (string-as-code)\n",
                    n, addr, (uint32_t)ctx->lr, (uint32_t)ctx->gpr[3]);
        if (addr == last_a) streak++; else { last_a = addr; streak = 1; }
        ctx->gpr[3] = ps3_icall_skip_ret();
        { extern volatile int g_vdec_startseq_count;
          extern void* g_ce03c_play_abort; /* jmp_buf* when armed */
          if (g_ce03c_play_abort && g_vdec_startseq_count >= 2 && streak >= 12) {
            fprintf(stderr,
                    "[ICALL-ASCII] abort CE03C Play after StartSeq=%d (FO residual hang)\n",
                    g_vdec_startseq_count);
            fflush(stderr);
            streak = 0;
            longjmp(*(jmp_buf*)g_ce03c_play_abort, 1);
          }
        }
        return;
      }
    }

    /* R11 (PS3_TRACE_POSTTHR_PC / PS3_TRACE_SCHEDARM): log if CTR lands on
     * menu-arm EAs. Offline OPD: B94EC/B61F4 no OPD; B6150 OPD unreferenced —
     * expect zero hits if schedule never arms. Default OFF. */
    {
        static int menu_ctr = -1;
        if (menu_ctr < 0) {
            const char* a = getenv("PS3_TRACE_POSTTHR_PC");
            const char* b = getenv("PS3_TRACE_SCHEDARM");
            menu_ctr = ((a && a[0] == '1') || (b && b[0] == '1')) ? 1 : 0;
        }
        if (menu_ctr && (addr == 0x000B94ECu || addr == 0x000B6150u
                         || addr == 0x000B61F4u || addr == 0x000BB424u
                         || addr == 0x000BB4E0u)) {
            static int n = 0;
            if (n++ < 32)
                fprintf(stderr,
                        "[SCHEDARM-ICALL] ctr=0x%08X lr=0x%08X r3=0x%08X r12=0x%08X\n",
                        addr, (uint32_t)ctx->lr, (uint32_t)ctx->gpr[3],
                        (uint32_t)ctx->gpr[12]);
        }
    }

    /* PS3_TRACE_ICALL_TO=0xEA[,0xEA...]: quem despacha para uma EA guest.
     *
     * Medido a 2026-08-01: neste lift **nem o `lr` do guest nem o rbp frame
     * walk servem para atribuir uma chamada indirecta**. O `lr` fica preso no
     * ultimo `bl` (mandou a investigacao para a funcao errada durante uma
     * ronda inteira) e o frame walk, com trampolins e tail-calls, nao mapeia
     * 1:1 nas chamadas guest (apontou `func_0039D764`, cujos 224 despachos
     * medidos nao incluiam sequer o objecto em causa).
     *
     * O que sobra e' apanhar o despacho no proprio ponto de resolucao, com os
     * registos de argumento e a cadeia host simbolizada. Ate 8 moradas.
     * OFF por default: uma leitura de contador e um branch no caminho quente. */
    ps3_trace_icall_to(addr, ctx, "call");

    ppu_fn fn = ppu_lookup(addr);
    if (fn) {
        /* Recursion-depth guard: a malformed/cyclic jump table (or a tail-call
         * chain that never converges) can dispatch recursively without bound
         * and blow the host stack. Cap the depth, log once, then unwind. */
        static thread_local int s_depth = 0;
        if (s_depth > 4000) {
            static int warned = 0;
            if (warned++ < 8)
                fprintf(stderr, "[ppu] recursion cap @0x%08X depth=%d -- skipping\n", addr, s_depth);
            /* At the cap, the GUEST link register and key regs identify the
             * looping caller (host backtraces are useless here: -O0 MinGW
             * frames lack unwind info, RtlCaptureStackBackTrace sees 1 frame). */
            if (warned <= 4) {
                fprintf(stderr, "  [rec-guest] lr=0x%08X r3=0x%08X r4=0x%08X r29=0x%08X r30=0x%08X r31=0x%08X\n",
                        (uint32_t)ctx->lr, (uint32_t)ctx->gpr[3], (uint32_t)ctx->gpr[4],
                        (uint32_t)ctx->gpr[29], (uint32_t)ctx->gpr[30], (uint32_t)ctx->gpr[31]);
                fflush(stderr);
            }
#if defined(__APPLE__)
            /* Host-stack high-water at the cap (gated, read-only): confirms the
             * cap is the binding limit and how much stack the climb consumed. */
            if (ppu_host_stack_probe_on() && warned <= 8)
                ppu_host_stack_sample("cap", s_depth);
#endif
            return;
        }
        /* Deep-recursion preemption: guest state machines loop by dispatching
         * through the jump table (bctr) -- on real HW that is a plain jump, but
         * here each iteration is a host call that stacks a frame. A thread
         * spinning in such a loop (e.g. a synchronous-IO wait polling for a
         * FIOS op) holds the giant lock the whole climb, so the very thread
         * that would complete the op never runs and the climb only ends at the
         * 4000 cap, whose skip corrupts the caller's result (observed: the
         * movie audio open failing instantly). Yield the giant periodically on
         * the way up so service threads can make progress. */
        if ((s_depth & 0x1FF) == 0x1FF &&
            (g_giant_waiters > 0 || g_giant_prio_waiters > 0) &&
            g_giant_holder_tid == (long)GetCurrentThreadId())
            ppu_store_preempt_point();
#if defined(__APPLE__)
        /* Host-stack climb sampler (gated, read-only): a few points on the way
         * up (depth 1023/2047/3071) so per-level cost is visible even on runs
         * that unwind before the 4000 cap. The cheap bitmask is checked first so
         * the common path short-circuits before the env lookup (zero cost off). */
        if ((s_depth & 0x3FF) == 0x3FF && ppu_host_stack_probe_on())
            ppu_host_stack_sample("climb", s_depth);
#endif
        s_depth++;
        fn(ctx);
        /* Drain the tail-call trampoline chain. Lifted functions model a tail
         * call (`b target`) by setting g_trampoline_fn and returning, expecting
         * the *caller's* DRAIN_TRAMPOLINE to continue. An indirect call IS such
         * a caller: if the dispatched function ends in a tail call, the
         * continuation is lost unless we drain it here too -- ppu_run only
         * drains the top frame, so without this the CRT's init tail-calls (and
         * the function-pointer tables they populate) silently never run. */
        while (g_trampoline_fn) {
            void (*tf)(void*) = g_trampoline_fn;
            g_trampoline_fn = 0;
            tf(ctx);
        }
        s_depth--;
        return;
    }
    /* Stuck-loop guard: a divergence (e.g. an object with a null function
     * pointer) can make the game spin on the same unresolved target forever.
     * Detect a long run of identical unresolved targets and bail so the run
     * stays fast and the log readable. */
    static uint32_t last = 0xFFFFFFFFu; static uint32_t streak = 0;
    uint32_t cur = (uint32_t)ctx->ctr;
    /* PS3_TRACE_ICALL_TARGET=0xHEX: unlike [ICALL-BAD] below (capped at the
     * first 12 unresolved targets seen all-run), this fires on every hit of
     * ONE specific bad ctr value, including inside a tight stuck-loop streak
     * that would otherwise never re-log (see "don't spam" return below). Added
     * to find who feeds ctr=0x40678C90 in the post-B71/AUTO_LOAD chain (gate6):
     * the guest LR here is the call site, stable across runs unlike host RBP
     * (which is a trampoline return and varies run to run). Gated, OFF by
     * default -- diagnostic only, no behavior change. */
    { static uint32_t target = 0; static int target_inited = 0, target_hits = 0;
      static uint64_t total_hits = 0; static int seen_target = 0;
      if (!target_inited) { target_inited = 1;
          const char* t = getenv("PS3_TRACE_ICALL_TARGET");
          target = (t && t[0]) ? (uint32_t)strtoul(t, NULL, 0) : 0; }
      if (target && cur == target) {
          total_hits++; seen_target = 1;
          if (total_hits <= 3 || (total_hits % 10000) == 0)
              fprintf(stderr, "[ICALL-TARGET] total_hits=%llu ctr=0x%08X (heartbeat)\n",
                      (unsigned long long)total_hits, cur);
      } else if (target && seen_target) {
          fprintf(stderr, "[ICALL-TARGET] EXITED loop after total_hits=%llu, new cur=0x%08X\n",
                  (unsigned long long)total_hits, cur);
          seen_target = 0; /* only report the first exit */
      }
      if (target && cur == target && target_hits < 3) {
          target_hits++;
          fprintf(stderr, "[ICALL-TARGET] hit=%d ctr=0x%08X lr=0x%08llX r2=0x%08llX r3=0x%08llX r9=0x%08llX r10=0x%08llX r11=0x%08llX r12=0x%08llX\n",
                  target_hits, cur, (unsigned long long)ctx->lr, (unsigned long long)ctx->gpr[2],
                  (unsigned long long)ctx->gpr[3], (unsigned long long)ctx->gpr[9],
                  (unsigned long long)ctx->gpr[10], (unsigned long long)ctx->gpr[11],
                  (unsigned long long)ctx->gpr[12]);
          /* r10 is func_002B2660's "vtable slot" pointer (gpr9+0xC): it should
           * hold a {code@+0, toc@+4} OPD-like pair. ctr(=target) came from
           * r10+0. Dump r10-0x10..+0x20 to see whether r10 is actually a
           * product-list NODE (next-pointer-first layout, same 0x4067xxxx
           * heap band as [TYPE15] product list log lines) misread as a
           * callback slot, rather than a real {code,toc} struct. */
          { uint32_t r9 = (uint32_t)ctx->gpr[9], r10 = (uint32_t)ctx->gpr[10];
            fprintf(stderr, "[ICALL-TARGET]   r9(obj)=0x%08X r10(slot)=0x%08X\n", r9, r10);
            if (r10 >= 0x10000u && r10 < 0x4F000000u) {
                uint32_t base = (r10 >= 0x10u) ? (r10 - 0x10u) : 0u;
                fprintf(stderr, "[ICALL-TARGET]   slot-0x10..+0x1C:");
                for (int wi = 0; wi < 12; wi++) {
                    uint32_t ea = base + (uint32_t)(wi * 4);
                    if (vm_oob(ea, 4)) { fprintf(stderr, " OOB"); continue; }
                    fprintf(stderr, " %08X", vm_read32(ea));
                }
                fprintf(stderr, "\n");
            }
            if (r9 >= 0x10000u && r9 < 0x4F000000u) {
                fprintf(stderr, "[ICALL-TARGET]   r9+0x0..+0x1C:");
                for (int wi = 0; wi < 8; wi++) {
                    uint32_t ea = r9 + (uint32_t)(wi * 4);
                    if (vm_oob(ea, 4)) { fprintf(stderr, " OOB"); continue; }
                    fprintf(stderr, " %08X", vm_read32(ea));
                }
                fprintf(stderr, "\n");
            }
          }
          fflush(stderr);
      }
    }
    /* On the FIRST unresolved-target hit, log the GUEST call site (LR) + regs.
     * The guest LR is unambiguous where host backtraces are not (tail calls). */
    { if (cur != 0 && cur != 0xC0DE1111u && !ppu_lookup(cur)) {
        static int firstlog = 0;
        if (firstlog++ < 12)
            fprintf(stderr, "[ICALL-BAD] ctr=0x%08X lr=0x%08llX r2=0x%08llX r3=0x%08llX r11=0x%08llX r12=0x%08llX\n",
                    cur, (unsigned long long)ctx->lr, (unsigned long long)ctx->gpr[2],
                    (unsigned long long)ctx->gpr[3], (unsigned long long)ctx->gpr[11],
                    (unsigned long long)ctx->gpr[12]);
        /* R2 Disc B / H1 evidence: dump guest words at r3/r12/ctr-0x10 once.
         * Gated PS3_TRACE_ICALL_BAD_MEM=1 (default OFF). Safe bounds only —
         * uncommitted/OOB → skip word (vm_read32 already degrades). No fix. */
        {
            static int memdump = -1;
            static int mem_done = 0;
            if (memdump < 0) {
                const char* v = getenv("PS3_TRACE_ICALL_BAD_MEM");
                memdump = (v && v[0] && v[0] != '0') ? 1 : 0;
            }
            if (memdump && !mem_done) {
                mem_done = 1;
                uint32_t bases[3] = {
                    (uint32_t)ctx->gpr[3],
                    (uint32_t)ctx->gpr[12],
                    (cur >= 0x10u) ? (cur - 0x10u) : 0u,
                };
                const char* labels[3] = { "r3", "r12", "ctr-0x10" };
                for (int bi = 0; bi < 3; bi++) {
                    uint32_t base = bases[bi];
                    fprintf(stderr, "[ICALL-BAD-MEM] %s base=0x%08X words16:",
                            labels[bi], base);
                    if (base == 0 || base + 64u < base /* wrap */) {
                        fprintf(stderr, " (skip)\n");
                        continue;
                    }
                    for (int wi = 0; wi < 16; wi++) {
                        uint32_t ea = base + (uint32_t)(wi * 4);
                        if (vm_oob(ea, 4)) {
                            fprintf(stderr, " OOB");
                            continue;
                        }
                        /* vm_read32 returns 0 on uncommitted (logs UNCOMMITTED). */
                        uint32_t w = vm_read32(ea);
                        fprintf(stderr, " %08X", w);
                    }
                    fprintf(stderr, "\n");
                }
                fflush(stderr);
            }
        }
      } }
    if (cur == last) {
        /* PS3_STUCK_ICALL_LIMIT: diagnostic-only override of the abort
         * threshold below (default unchanged: 2000). Added to test whether
         * the gate6 AUTO_LOAD ctr=0x40678C90 spin (func_002B2E04's
         * `while (*flag) func_002B2DD0(ctx);` poll -- see notes 2026-07-31)
         * is a genuine deadlock or a race that a concurrent thread eventually
         * resolves given more iterations. OFF (i.e. =2000) unless set. */
        static uint32_t limit = 0;
        if (!limit) { const char* l = getenv("PS3_STUCK_ICALL_LIMIT");
            limit = (l && l[0]) ? (uint32_t)strtoul(l, NULL, 0) : 2000u; }
        if (++streak == limit) {
            fprintf(stderr, "[ppu] FATAL: stuck calling 0x%08X (%u times) -- aborting run\n", cur, streak);
            /* Host RBP-walk (same technique as the watchdog in boot_main.cpp)
             * to see the FULL native call chain leading here, not just the
             * immediate __builtin_return_address(0) caller -- with tail-call
             * flattening and nested ps3_indirect_call re-entrancy, the
             * immediate caller alone has repeatedly proven ambiguous this
             * session (traced-but-wrong function on more than one occasion). */
            { void** rbp = (void**)__builtin_frame_address(0);
              /* Only follow rbp while it stays inside our own stack region --
               * lifted-game frames can hold garbage in the saved-rbp slot and
               * dereferencing it has produced a real SIGSEGV before. */
              uintptr_t stack_lo = (uintptr_t)rbp, stack_hi = stack_lo + 0x200000u;
              fprintf(stderr, "[ppu] rbp frame walk:\n");
              for (int i = 0; i < 15 && rbp; i++) {
                  if ((uintptr_t)rbp < stack_lo || (uintptr_t)rbp + 0x50 >= stack_hi || ((uintptr_t)rbp & 7)) {
                      fprintf(stderr, "  #%d rbp=%p (left stack region, stopping)\n", i, (void*)rbp);
                      break;
                  }
                  void* ret = rbp[1];
                  /* Simbolizar por dladdr: para codigo liftado da o
                   * func_<EA guest> envolvente. Um ret cru nao serve entre
                   * corridas (ASLR) e este walk e' precisamente o que nomeia
                   * quem esta preso. */
                  { Dl_info di;
                    if (dladdr(ret, &di) && di.dli_sname)
                        fprintf(stderr, "  #%d rbp=%p ret=%s+0x%lX\n", i, (void*)rbp,
                                di.dli_sname,
                                (unsigned long)((const char*)ret - (const char*)di.dli_saddr));
                    else if (dladdr(ret, &di) && di.dli_fbase)
                        fprintf(stderr, "  #%d rbp=%p ret=img+0x%lX\n", i, (void*)rbp,
                                (unsigned long)((const char*)ret - (const char*)di.dli_fbase));
                    else
                        fprintf(stderr, "  #%d rbp=%p ret=%p\n", i, (void*)rbp, ret); }
                  void** next = (void**)rbp[0];
                  if (next <= rbp) break;
                  rbp = next;
              } }
            fflush(stderr);
            exit(3);
        }
        return;   /* don't spam the log on a tight retry loop */
    }
    last = cur; streak = 0;
    fprintf(stderr, "[ppu] unresolved indirect call -> 0x%08X\n", (uint32_t)ctx->ctr);
    static int dumped = 0;
    if (dumped < 8) {
        dumped++;
        /* Simbolizar os 3 primeiros ra via dladdr, como o [OOBRA] e o
         * [WATCHSTORE] ja fazem: para codigo liftado devolve o func_<EA guest>
         * envolvente, que e' a unica coisa util aqui. O `lr` do guest NAO
         * serve para atribuir uma chamada indirecta -- o lift so' o escreve
         * antes dos `bl`, por isso fica preso no ultimo salto directo e ja
         * apontou para a funcao errada nesta sessao (2026-08-01: o
         * lr=0x0024E2D4 mandou-me para o walker func_0024D5BC, que a sonda
         * PS3_TRACE_D5BC provou estar saudavel -- 758 nos com vtable/OPD/code
         * validos). Um ponteiro host cru nao serve entre corridas por causa
         * do ASLR; o nome do simbolo serve. */
        {
            void* ra[3] = { __builtin_return_address(0),
                            __builtin_return_address(1),
                            __builtin_return_address(2) };
            fprintf(stderr, "      host_ra:");
            for (int j = 0; j < 3; j++) {
                Dl_info di;
                if (dladdr(ra[j], &di) && di.dli_sname)
                    fprintf(stderr, " ra%d=%s+0x%lX", j, di.dli_sname,
                            (unsigned long)((const char*)ra[j] - (const char*)di.dli_saddr));
                else if (dladdr(ra[j], &di) && di.dli_fbase)
                    fprintf(stderr, " ra%d=img+0x%lX", j,
                            (unsigned long)((const char*)ra[j] - (const char*)di.dli_fbase));
                else
                    fprintf(stderr, " ra%d=%p", j, ra[j]);
            }
            fprintf(stderr, "%c", 10);
        }
        fprintf(stderr, "      lr=0x%08X r2=0x%08X r3=0x%08X r11=0x%08X r12=0x%08X\n",
                (uint32_t)ctx->lr, (uint32_t)ctx->gpr[2], (uint32_t)ctx->gpr[3],
                (uint32_t)ctx->gpr[11], (uint32_t)ctx->gpr[12]);
        for (int r = 0; r < 32; r += 8)
            fprintf(stderr, "      r%-2d: %08X %08X %08X %08X %08X %08X %08X %08X\n", r,
                (uint32_t)ctx->gpr[r+0],(uint32_t)ctx->gpr[r+1],(uint32_t)ctx->gpr[r+2],(uint32_t)ctx->gpr[r+3],
                (uint32_t)ctx->gpr[r+4],(uint32_t)ctx->gpr[r+5],(uint32_t)ctx->gpr[r+6],(uint32_t)ctx->gpr[r+7]);
    }
    /* FIX (confirmed 2026-07-02): every confirmed instance of an unresolved
     * indirect call this session (0xFF000000, 0xC0DE1111, 0x005165A0 --
     * the last one a data-segment address that was never even lifted as
     * code, all with tell-tale uninitialized-memory neighbors like
     * DEADBEEF nearby) turned out to be a virtual/optional method call
     * through a not-yet-populated slot, where the CALLER's own logic
     * already treats gpr3==0 as "no result / nothing to do" immediately
     * after the call (the same idiom confirmed at three separate call
     * sites: func_001E7C44, func_0014A01C, and the ps3_indirect_call
     * 0xC0DE1111 special-case above). Leaving gpr3 at its undefined
     * pre-call value instead let the caller misread stale/garbage data as
     * a real chained result, cascading through more garbage addresses
     * until the stuck-call guard above aborted the whole process. Clear
     * gpr3 unconditionally on any unresolved target -- strictly safer
     * than leaving it undefined, and matches every confirmed convention
     * seen so far. If a future caller turns out to need the pre-call
     * value preserved instead, that would show up as a NEW, different
     * symptom, not a silent regression. */
    ctx->gpr[3] = 0;
}

/* ---------------------------------------------------------------------------
 * ps3_indirect_tail — dispatch for `bctr` (branch to CTR, NO link).
 *
 * `bctr` and `bctrl` are different instructions and the lifter already tells
 * them apart (`ps3_indirect_call(ctx); return;` vs
 * `ps3_indirect_call(ctx); DRAIN_TRAMPOLINE(ctx);`), but BOTH ended up going
 * through ps3_indirect_call, which is a host CALL. On the real CPU `bctr` is a
 * JUMP: it consumes no stack. Routing it through a host call turns every guest
 * jump-table loop into unbounded host recursion.
 *
 * MEASURED (2026-07-20, macOS/arm64, 16 boots): the intro movie player's pump
 * `func_002C0508` loops by dispatching `[obj+0x620]` through the jump table at
 * guest 0x002C0594 (`bctr`, opcode 0x4E800420 in EBOOT.ELF). While it waits for
 * the FIOS open op it polls `func_002B4224` -> `[op+0x90]`, which the "fios
 * scheduler" PPU thread sets via func_0030644C. Each poll iteration stacked a
 * host frame, so the loop always hit the 4000-deep recursion cap
 * (`recursion cap @0x002C07D8` when still in state 1, `@0x002C05F8` once it had
 * reached state 3) -- 16/16 runs. The cap's `return` unwinds the pump, so the
 * player stops polling forever: whether the intro left st620=1 was a pure race
 * between the FIOS scheduler and the 4000-frame budget (5/16 runs won it).
 *
 * Tail-dispatching instead (set g_trampoline_fn and return, exactly the way the
 * lift already models `b target`) makes the loop iterative in the caller's
 * DRAIN_TRAMPOLINE, with zero stack growth -- which is what the hardware does.
 * Verified precondition: all 116314 direct lifted call sites in this lift are
 * followed by DRAIN_TRAMPOLINE, and every host entry into guest code
 * (ppu_run, ps3_indirect_call, boot_macos' thread proc) drains too, so a
 * trampoline set here is always executed by the caller.
 *
 * Falls back to ps3_indirect_call for anything that is not a lifted function
 * (address 0 / 0xC0DE1111 sentinels, import thunks, unresolved targets), so
 * those keep their existing behaviour bit for bit.
 *
 * PS3_BCTR_HOSTCALL=1 restores the old host-call behaviour (kill switch and
 * A/B arm; the fix is ON by default because it is the faithful one).
 * -----------------------------------------------------------------------*/
extern "C" void ps3_indirect_tail(ppu_context* ctx)
{
    static int s_hostcall = -1;
    if (s_hostcall < 0) {
        const char* v = getenv("PS3_BCTR_HOSTCALL");
        s_hostcall = (v && v[0] && v[0] != '0') ? 1 : 0;
    }
    if (!s_hostcall) {
        uint32_t addr = (uint32_t)ctx->ctr;
        if (addr != 0 && addr != 0xC0DE1111u) {
            /* PS3_TRACE_ICALL_TO tambem AQUI. Ponto cego medido a 2026-08-01:
             * func_00220F88 corre (os seus tail-calls para func_00220284
             * executam 13 vezes por corrida) mas o tracer no ps3_indirect_call
             * dava ZERO -- porque este e' o caminho do `bctr`, com o seu
             * proprio ppu_lookup. Um tracer que so cobre metade dos
             * despachantes mente por omissao, e a omissao parece prova. */
            ps3_trace_icall_to(addr, ctx, "tail");
            ppu_fn fn = ppu_lookup(addr);
            if (fn) {
                /* No extra giant-lock yield here on purpose. The obvious move
                 * -- port the every-512-frames preempt from ps3_indirect_call
                 * -- is wrong: there the counter is the CALL DEPTH, so it
                 * crosses a multiple of 512 at most ~8 times per climb; a
                 * counter of tail dispatches crosses one every 512 jumps for
                 * the whole boot. Measured: that variant cost ~3x boot
                 * throughput (30-47k log lines/25s vs 57-140k) and starved the
                 * very FIOS scheduler it was meant to help. Long-running guest
                 * loops are already preempted generically by the store-tick in
                 * ppu_rsv_on_store. */
                g_trampoline_fn = (void (*)(void*))fn;
                return;
            }
        }
    }
    ps3_indirect_call(ctx);
}

/* Called when lifted code branches to a function that wasn't in this lift
 * (subset/incremental builds). Logs the first few; returns so execution can
 * continue (the result is undefined, but it won't crash the link). */
extern "C" void ppu_unlifted_stub(uint64_t addr, ppu_context* ctx)
{
    (void)ctx;
    static int logged = 0;
    if (logged < 20) {
        fprintf(stderr, "[ppu] call to unlifted function 0x%08X\n", (uint32_t)addr);
        logged++;
    }
}

/* The real lv2 syscall table (runtime/syscalls/lv2_register.c). */
extern "C" int lv2_try_syscall(ppu_context* ctx);

/* lv2 syscall dispatch: r11 = syscall number, args in r3.. (PPC ABI).
 * A few syscalls the CRT needs at boot are handled inline (boot-tuned); the
 * rest are dispatched to the real lv2 table, and only genuinely-unregistered
 * numbers fall through to the return-CELL_OK stub. */
static void lv2_syscall_impl(ppu_context* ctx);

/* Funil 1 de 2 por onde o codigo liftado alcanca o host. Com
 * PS3_GIANT_HLE_ONLY o giant lock e' TOMADO AQUI em vez de na entrada da
 * thread; sem a flag, o chamador ja' o tem e isto e' uma chamada directa. */
/* ---- winport v75-syswait (engine_fixes_v75_syswait.py): WINPORT_SYSWAIT=1 per-thread call wait table ---- */
#ifdef _WIN32
extern "C" const char* wp75_hle_name(uint32_t nid);
static int wp75_state = -1;
static SRWLOCK wp75_lock = SRWLOCK_INIT;
struct Wp75E { unsigned long tid; unsigned long long key; long long ns; long long n; };
static Wp75E wp75_t[1024];
static long long wp75_fq, wp75_last;
extern "C" int wp75_on(void)
{
    if (wp75_state < 0) { const char* e = getenv("WINPORT_SYSWAIT"); wp75_state = (e && e[0] == '1') ? 1 : 0;
        if (wp75_state) { LARGE_INTEGER f; QueryPerformanceFrequency(&f); wp75_fq = f.QuadPart;
                          fprintf(stderr, "[SYSW75] per-thread syscall / HLE wait table ON\n"); fflush(stderr); } }
    return wp75_state;
}
extern "C" long long wp75_now(void) { LARGE_INTEGER t; QueryPerformanceCounter(&t); return t.QuadPart; }
static void wp75_report_locked(long long now)
{
    unsigned long tids[16]; long long tot[16]; int nt = 0;
    for (int i = 0; i < 1024; i++) {
        if (!wp75_t[i].n) continue;
        int k; for (k = 0; k < nt; k++) if (tids[k] == wp75_t[i].tid) break;
        if (k == nt) { if (nt == 16) continue; tids[nt] = wp75_t[i].tid; tot[nt] = 0; nt++; }
        tot[k] += wp75_t[i].ns;
    }
    const double secs = (double)(now - wp75_last) / (double)wp75_fq;
    for (int k = 0; k < nt; k++) {
        const double ms = (double)tot[k] / 1e6 / secs;
        if (ms < 20.0) continue;
        char line[900]; int o = snprintf(line, sizeof line, "[SYSW75] tid=%lu in-calls=%.0fms/s:", tids[k], ms);
        for (int r = 0; r < 6; r++) {
            int b = -1;
            for (int i = 0; i < 1024; i++) if (wp75_t[i].n && wp75_t[i].tid == tids[k] && wp75_t[i].ns >= 0 && (b < 0 || wp75_t[i].ns > wp75_t[b].ns)) b = i;
            if (b < 0) break;
            const unsigned long long key = wp75_t[b].key;
            char nm[64];
            if (key == 0xFFFFFFFFull) snprintf(nm, sizeof nm, "giant-preempt");   /* winport v75b-syswait-giant */
            else if (key == 0xFFFFFFFEull) snprintf(nm, sizeof nm, "giant-acquire");
            else if (key == 0xFFFFFFFDull) snprintf(nm, sizeof nm, "giant-priowait");   /* winport v75c-syswait-acq */
            else if (key >> 32) snprintf(nm, sizeof nm, "%s", wp75_hle_name((uint32_t)key)); else snprintf(nm, sizeof nm, "sc%llu", key);
            if (o < (int)sizeof line - 1)
                o += snprintf(line + o, sizeof line - (size_t)o, " %s %.1fms/%.0f", nm, (double)wp75_t[b].ns / 1e6 / secs, (double)wp75_t[b].n / secs);
            wp75_t[b].ns = -1 - wp75_t[b].ns;   /* mark taken (restored below) */
        }
        fprintf(stderr, "%s\n", line);
    }
    for (int i = 0; i < 1024; i++) { wp75_t[i].ns = 0; wp75_t[i].n = 0; wp75_t[i].tid = 0; }
    fflush(stderr);
}
extern "C" void wp75_add(unsigned long long key, long long t0)
{
    const long long now = wp75_now();
    const long long ns = (now - t0) * 1000000000ll / wp75_fq;
    const unsigned long tid = GetCurrentThreadId();
    AcquireSRWLockExclusive(&wp75_lock);
    unsigned h = (unsigned)((key * 2654435761ull) ^ (tid * 40503u)) & 1023u;
    for (int p = 0; p < 1024; p++, h = (h + 1) & 1023u) {
        if (!wp75_t[h].n) { wp75_t[h].tid = tid; wp75_t[h].key = key; wp75_t[h].ns = ns; wp75_t[h].n = 1; break; }
        if (wp75_t[h].tid == tid && wp75_t[h].key == key) { wp75_t[h].ns += ns; wp75_t[h].n++; break; }
    }
    if (!wp75_last) wp75_last = now;
    if (now - wp75_last >= wp75_fq) { wp75_report_locked(now); wp75_last = now; }
    ReleaseSRWLockExclusive(&wp75_lock);
}
#else
extern "C" int wp75_on(void) { return 0; }
extern "C" long long wp75_now(void) { return 0; }
extern "C" void wp75_add(unsigned long long key, long long t0) { (void)key; (void)t0; }
#endif
/* ---- end winport v75-syswait ---- */
extern "C" void lv2_syscall(ppu_context* ctx)
{
    if (wp75_on()) { const unsigned long long k75 = ctx->gpr[11]; const long long t75 = wp75_now();   /* winport v75-syswait */
        if (!ppu_giant_hle_only()) lv2_syscall_impl(ctx);
        else { ppu_giant_lock_acquire(); lv2_syscall_impl(ctx); if (ppu_giant_lock_held_by_caller()) ppu_giant_lock_release(); }
        wp75_add(k75, t75); return; }
    if (!ppu_giant_hle_only()) { lv2_syscall_impl(ctx); return; }
    ppu_giant_lock_acquire();
    lv2_syscall_impl(ctx);
    /* Alguns handlers largam e retomam o lock a' volta de esperas; se algum
     * caminho sair sem ele, nao largar duas vezes. */
    if (ppu_giant_lock_held_by_caller())
        ppu_giant_lock_release();
}

static void lv2_syscall_impl(ppu_context* ctx)
{
    { extern void ppu_blockmark_set(const char*, unsigned long long);
      ppu_blockmark_set("lv2_syscall", (unsigned long long)ctx->gpr[11]); }
    uint64_t num = ctx->gpr[11];
    switch (num) {
    case 352: {   /* sys_memory_get_user_memory_size(sys_memory_info_t* info)
                   * info = { u32 total_user_memory; u32 available_user_memory } */
        uint32_t info = (uint32_t)ctx->gpr[3];
        if (info) { vm_write32(info + 0, 0x10000000u);   /* 256 MB total */
                    vm_write32(info + 4, 0x0C000000u); } /* 192 MB available */
        fprintf(stderr, "[lv2] get_user_memory_size(info=0x%X) -> total=256MB avail=192MB\n", info);
        ctx->gpr[3] = 0;
        return;
    }
    case 330: {   /* sys_mmapper_allocate_address(u64 size, u64 flags,
                   * u64 alignment, u32* alloc_addr) -> reserve guest VA range */
        static uint32_t s_next_va = 0x11000000u;   /* just past the loaded image */
        uint32_t size  = (uint32_t)ctx->gpr[3];
        uint32_t align = (uint32_t)ctx->gpr[5];
        uint32_t out   = (uint32_t)ctx->gpr[6];
        if (align < 0x100000u) align = 0x100000u;   /* 1 MB min */
        s_next_va = (s_next_va + align - 1) & ~(align - 1);
        uint32_t va = s_next_va;
        s_next_va += (size + 0xFFFFFu) & ~0xFFFFFu;
        if (out) vm_write32(out, va);
        ctx->gpr[3] = 0;
        return;
    }
    case 403: {   /* sys_tty_write(s32 ch, cptr buf, u32 len, ptr pwritelen) */
        uint32_t ch   = (uint32_t)ctx->gpr[3];
        uint32_t buf  = (uint32_t)ctx->gpr[4];
        uint32_t len  = (uint32_t)ctx->gpr[5];
        uint32_t pwl  = (uint32_t)ctx->gpr[6];
        uint32_t wlen = len;

        /* DIAG (2026-07-02, PS3_TRACE_SHADERMSG): find who formats+emits the
         * game's own "Invalid shader combination" CGOWShader message, via
         * the same host RBP-walk technique used elsewhere this session
         * (build -O0 keeps a standard frame pointer in every lifted func).
         * printf-style output can arrive as several small tty_write calls, so
         * accumulate into a rolling buffer instead of matching one call at a
         * time (a per-call substring check would miss a hit split across two
         * writes). */
        { static int on = -1; if (on < 0) on = getenv("PS3_TRACE_SHADERMSG") ? 1 : 0;
          if (on && buf && len > 0 && len < 0x4000 && ppu_vm_size && buf + len <= ppu_vm_size) {
              static char roll[512]; static uint32_t roll_len = 0;
              uint32_t n = len < 400 ? len : 400;
              if (roll_len + n > sizeof(roll) - 1) {
                  uint32_t keep = sizeof(roll) / 2;
                  memmove(roll, roll + (roll_len - keep), keep);
                  roll_len = keep;
              }
              for (uint32_t i = 0; i < n; i++) roll[roll_len++] = (char)vm_read8(buf + i);
              roll[roll_len] = '\0';

              if (strstr(roll, "Invalid shader") || strstr(roll, "PRECALCULATED")) {
                  static int shown = 0;
                  if (shown < 8) {
                      shown++;
                      fprintf(stderr, "[SHADERMSG] this call: buf=0x%08X len=%u text=\"%.60s\"\n", buf, len, (char*)vm_base + buf);
                      fprintf(stderr, "[SHADERMSG] rolling context: \"%s\"\n", roll);
#ifdef _WIN32
                      uintptr_t base = (uintptr_t)GetModuleHandleW(NULL);
                      unsigned long long rbp = (unsigned long long)__builtin_frame_address(0);
                      fprintf(stderr, "  rbp walk (module base=0x%p):\n", (void*)base);
                      for (int depth = 0; depth < 24 && rbp; depth++) {
                          unsigned long long* frame = (unsigned long long*)rbp;
                          unsigned long long saved_rbp = frame[0], ret = frame[1];
                          unsigned long long nm = ret >= base ? ret - base + 0x140000000ull : 0;
                          fprintf(stderr, "    #%d rbp=0x%016llX ret=0x%016llX (nm=0x%llX)\n", depth, rbp, ret, nm);
                          if (!saved_rbp || saved_rbp <= rbp) break;
                          rbp = saved_rbp;
                      }
#endif
                      fflush(stderr);
                  }
                  roll_len = 0; /* avoid re-matching the same text on every subsequent call */
              }
          } }
        if (wlen > 0x4000u) {   /* guard against garbage len (divergence dumps memory) */
            static int n = 0;
            if (n < 20) { fprintf(stderr, "[tty] suspicious len=%u (buf=0x%08X) dropped\n", len, buf); n++; }
            /* Do not fputc 16KB of junk: that stalled GoW2 before the title
             * (flips frozen, PPU stuck in sys_tty_write). Guest still sees OK. */
            wlen = 0;
        }
        /* TRACE (diagnostic, remove before commit): host RBP-walk when the
         * game prints an exception message -- captures the catch-handler chain */
        { static int xl=-1; if(xl<0) xl = getenv("PS3_TRACE_XLEN")?1:0;
          if (xl && buf && wlen>4 && wlen<0x1000 && ppu_vm_size && buf+wlen<=ppu_vm_size) {
              char tmp[128]; uint32_t tn = wlen<127?wlen:127;
              for (uint32_t i2=0;i2<tn;i2++) tmp[i2]=(char)vm_read8(buf+i2);
              tmp[tn]='\0';
              if (strstr(tmp,"exception")||strstr(tmp,"too long")) {
                  static int shown=0;
                  if (shown<3) { shown++;
                      fprintf(stderr,"[XLENTTY] \"%.60s\"\n",tmp);
#ifdef _WIN32
                      uintptr_t base=(uintptr_t)GetModuleHandleW(NULL);
                      unsigned long long rbp=(unsigned long long)__builtin_frame_address(0);
                      unsigned long long lo=rbp, hi=rbp+0x200000ull;
                      fprintf(stderr,"[XLENTTY] rbp walk:\n");
                      for (int d=0; d<24 && rbp; d++) {
                          if(rbp<lo||rbp+0x50>=hi||(rbp&7)) break;
                          unsigned long long* fr=(unsigned long long*)rbp;
                          unsigned long long nm = fr[1]>=base ? fr[1]-base+0x140000000ull : 0;
                          fprintf(stderr,"    #%d ret=0x%llX (nm=0x%llX)\n",d,fr[1],nm);
                          if(!fr[0]||fr[0]<=rbp) break; rbp=fr[0];
                      }
#endif
                      fflush(stderr);
                  }
              }
          } }
        FILE* out = stdout;   /* keep all TTY on stdout, clean of [ppu] logs */
        for (uint32_t i = 0; i < wlen; i++) {
            if (ppu_vm_size && buf + i >= ppu_vm_size) break;
            fputc(vm_read8(buf + i), out);
        }
        fflush(out);
        if (pwl) vm_write32(pwl, len);
        ctx->gpr[3] = 0;
        return;
    }
    default: {
        /* DIAG: env-gated syscall trap — log first 2 + every 5000th occurrence
         * of each number with the recompiled caller's return address, to find
         * which loop/func is spinning or blocking. nm --numeric-sort maps the
         * ra to a func_<ADDR>. */
        { static int on = -1; if (on < 0) on = getenv("PS3_TRACE_SC") ? 1 : 0;
          if (on) { static unsigned long long c[1024] = {0};
                    unsigned idx = (num < 1024) ? (unsigned)num : 1023u;
                    c[idx]++;
                    static int s_tid_ctr = 0;
                    static thread_local int s_tid = 0;
                    if (!s_tid) s_tid = ++s_tid_ctr;
                    if (num == 141 && c[idx] <= 1) {   /* spin obj-chain probe: gpr31=[0x53FD40]=S, obj=[S], flag=obj->u8[4] */
                        uint32_t S = (uint32_t)ctx->gpr[31];
                        uint32_t obj = S ? vm_read32(S) : 0;
                        fprintf(stderr, "[SPIN] S=0x%08X obj=0x%08X flag=%u\n",
                                S, obj, obj ? (unsigned)vm_read8(obj + 4) : 0xFFu);
                        fflush(stderr);
                    }
                    if (c[idx] <= 2 || (c[idx] % 200000) == 0) {
                        fprintf(stderr, "[SC] T%d num=%llu #%llu r3=0x%llX r4=0x%llX r5=0x%llX ra=%p\n",
                                s_tid, (unsigned long long)num, c[idx],
                                (unsigned long long)ctx->gpr[3],
                                (unsigned long long)ctx->gpr[4],
                                (unsigned long long)ctx->gpr[5], __builtin_return_address(0));
                        fflush(stderr);
                    } } }
        /* Consult the real lv2 syscall table (semaphore / mutex / cond /
         * rwlock / event / timer / memory / vm / fs / spu). Initialised by
         * lv2_init_syscalls() at boot. Unregistered numbers fall through to the
         * return-0 stub below (which is what got the CRT this far). */
        if (lv2_try_syscall(ctx))
            return;
        static int logged = 0;
        if (logged < 30) {
            fprintf(stderr, "[ppu] lv2_syscall %llu (stub)\n", (unsigned long long)num);
            logged++;
        }
        ctx->gpr[3] = 0;   /* CELL_OK */
        return;
    }
    }
}

/* ---------------------------------------------------------------------------
 * Minimal big-endian ELF64 loader: copies PT_LOAD segments into vm_base at
 * their vaddrs and zero-fills BSS (memsz > filesz). Returns e_entry (an OPD
 * address) or 0 on error. Assumes vm_base is allocated large enough.
 * -----------------------------------------------------------------------*/
static uint16_t be16(const uint8_t* p) { return (uint16_t)((p[0] << 8) | p[1]); }
static uint32_t be32(const uint8_t* p) { return ((uint32_t)p[0] << 24) | (p[1] << 16) | (p[2] << 8) | p[3]; }
static uint64_t be64(const uint8_t* p) { return ((uint64_t)be32(p) << 32) | be32(p + 4); }

#include "ps3emu/ps3_patch.h"

extern "C" uint32_t ppu_load_elf(const char* path)
{
    ps3_patch_range pr_loaded[16], pr_exec[16];
    int n_loaded = 0, n_exec = 0;
    FILE* f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "[ppu] cannot open %s\n", path); return 0; }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t* file = (uint8_t*)malloc(sz);
    if (!file || fread(file, 1, sz, f) != (size_t)sz) { fclose(f); free(file); return 0; }
    fclose(f);

    if (sz < 64 || memcmp(file, "\x7F""ELF", 4) != 0 || file[4] != 2 /*ELFCLASS64*/ || file[5] != 2 /*MSB*/) {
        fprintf(stderr, "[ppu] not a 64-bit big-endian ELF\n"); free(file); return 0;
    }
    uint64_t fsz = (uint64_t)sz;
    uint32_t entry = (uint32_t)be64(file + 24);
    uint64_t phoff = be64(file + 32);
    uint16_t phentsize = be16(file + 54);
    uint16_t phnum = be16(file + 56);

    int loaded = 0;
    for (uint16_t i = 0; i < phnum; i++) {
        uint64_t ph_off = phoff + (uint64_t)i * phentsize;
        if (ph_off + 56 > fsz) break;   /* program header itself out of the file */
        const uint8_t* ph = file + ph_off;
        uint32_t p_type = be32(ph + 0);
        if (p_type == 0x60000002u /*PT_PROC_PRX_PARAM*/) {
            /* sys_prx_param: its .lib.stub table drives firmware import fixup.
             * Captured here for ppu_resolve_imports() (runtime/ppu/ppu_imports.cpp). */
            ppu_prx_param_va = (uint32_t)be64(ph + 16);   /* p_vaddr */
            fprintf(stderr, "[ppu] PT_PROC_PRX_PARAM vaddr=0x%08X\n", ppu_prx_param_va);
            continue;
        }
        if (p_type == 7 /*PT_TLS*/) {
            /* The thread-local template: its initialised bytes live in vm_base
             * at p_vaddr (covered by a PT_LOAD too). ppu_run copies it into the
             * main thread's TLS image and points r13 at it. */
            g_tls_vaddr  = (uint32_t)be64(ph + 16);
            g_tls_filesz = (uint32_t)be64(ph + 32);
            g_tls_memsz  = (uint32_t)be64(ph + 40);
            fprintf(stderr, "[ppu] PT_TLS template vaddr=0x%08X filesz=0x%X memsz=0x%X\n",
                    g_tls_vaddr, g_tls_filesz, g_tls_memsz);
            continue;
        }
        if (p_type != 1 /*PT_LOAD*/) continue;
        uint64_t p_offset = be64(ph + 8);
        uint64_t p_vaddr  = be64(ph + 16);
        uint64_t p_filesz = be64(ph + 32);
        uint64_t p_memsz  = be64(ph + 40);
        if (p_memsz == 0) continue;
        /* Bounds-check both ends before touching host memory: the source range
         * must lie inside the ELF file, and the destination range inside the
         * guest VM (ppu_vm_size==0 = unchecked, matching the vm accessors).
         * Skip malformed/oversized segments rather than overflowing the host. */
        if (p_offset > fsz || p_filesz > fsz || p_offset + p_filesz > fsz) {
            fprintf(stderr, "[ppu] segment %u file range 0x%llX+0x%llX exceeds ELF (0x%llX), skipped\n",
                    i, (unsigned long long)p_offset, (unsigned long long)p_filesz, (unsigned long long)fsz);
            continue;
        }
        if (ppu_vm_size && (p_vaddr > ppu_vm_size || p_memsz > ppu_vm_size ||
                            p_vaddr + p_memsz > ppu_vm_size)) {
            fprintf(stderr, "[ppu] segment %u vaddr 0x%llX+0x%llX exceeds VM (0x%X), skipped\n",
                    i, (unsigned long long)p_vaddr, (unsigned long long)p_memsz, ppu_vm_size);
            continue;
        }
        memcpy(vm_base + (uint32_t)p_vaddr, file + p_offset, (size_t)p_filesz);
        if (p_memsz > p_filesz)
            memset(vm_base + (uint32_t)p_vaddr + (uint32_t)p_filesz, 0, (size_t)(p_memsz - p_filesz));
        loaded++;
        if (n_loaded < 16)
            pr_loaded[n_loaded++] = { (uint32_t)p_vaddr, (uint32_t)(p_vaddr + p_memsz) };
        if ((be32(ph + 4) & 1u /*PF_X*/) && n_exec < 16)
            pr_exec[n_exec++] = { (uint32_t)p_vaddr, (uint32_t)(p_vaddr + p_memsz) };
    }
    free(file);
    fprintf(stderr, "[ppu] loaded %d PT_LOAD segments, entry OPD 0x%08X\n", loaded, entry);
    /* Game patches (RPCS3 patch.yml style), resolved by the launcher into
     * PS3_PATCH_FILE. Applied once, before any guest code runs. */
    if (const char* pf = getenv("PS3_PATCH_FILE"))
        ps3_patch_apply_file(pf, vm_base, pr_loaded, n_loaded, pr_exec, n_exec);
    /* Task 2 (bringup-instrumentacao-fase0): ELF_LOADED -- fim do
     * carregamento do ELF guest (todos os PT_LOAD copiados para vm_base). */
    ps3_checkpoint_fire(PS3_CP_ELF_LOADED, "ppu_load_elf",
                       "segments=%d entry_opd=0x%08X", loaded, entry);
    return entry;
}

/* Resolve an OPD descriptor {u32 func, u32 toc}. */
extern "C" int ppu_opd_resolve(uint32_t opd, uint32_t* code, uint32_t* toc)
{
    /* PS3_TRACE_OPD_BAD: quem passa um OPD que nao e' um OPD.
     *
     * Medido a 2026-08-01 no caminho do ICGLdrShader: o resolver e' chamado com
     * opd=0x65726D61 -- "erma" em ASCII, de R_P-erma, o nome do WAD de 20 MB.
     * A tabela de componentes tem STRINGS onde deviam estar ponteiros de OPD, e
     * o jogo responde com a sua propria mensagem: "Unknown component
     * 0xf85f9b1e in component loader ICGLdrShader."
     *
     * O `lr` do guest nao serve para atribuir isto (licao repetida cinco vezes
     * nesta sessao); o que serve e' a cadeia host simbolizada por dladdr, que
     * para codigo liftado da' o func_<EA guest> envolvente. Gated, OFF por
     * default, cap configuravel. */
    { static int on = -1; static int cap = 0;
      if (on < 0) { const char* e = getenv("PS3_TRACE_OPD_BAD");
          on = (e && *e && *e != '0') ? 1 : 0;
          const char* c2 = getenv("PS3_TRACE_OPD_BAD_CAP");
          cap = (c2 && *c2) ? (int)strtol(c2, 0, 0) : 24;
          if (cap < 0) cap = 0x7FFFFFFF; }
      if (on && (opd < 0x10000u || opd >= 0x50000000u)) {
          static int k = 0;
          if (k++ < cap) {
              fprintf(stderr, "[OPD-BAD] opd=0x%08X (nao e' um OPD plausivel)", opd);
              void* ra[3] = { __builtin_return_address(0),
                              __builtin_return_address(1),
                              __builtin_return_address(2) };
              for (int j = 0; j < 3; j++) { Dl_info di;
                  if (dladdr(ra[j], &di) && di.dli_sname)
                      fprintf(stderr, " ra%d=%s+0x%lX", j, di.dli_sname,
                              (unsigned long)((const char*)ra[j] - (const char*)di.dli_saddr));
                  else fprintf(stderr, " ra%d=%p", j, ra[j]); }
              fprintf(stderr, "%c", 10); fflush(stderr);
          } } }
    uint32_t c = vm_read32(opd);
    uint32_t t = vm_read32(opd + 4);
    /* Direct-code-in-vtable recovery: some slots store a guest code EA where
     * an OPD pointer is expected. Reading {code,toc} then yields the first two
     * instruction words (observed: code=0x27182818 toc=0x20 after R_PermA). */
    if (ppu_lookup(opd) && !ppu_lookup(c)) {
        c = opd;
        t = 0; /* keep caller's TOC */
    }
    if (code) *code = c;
    if (toc)  *toc  = t;
    return c != 0;
}

/* Load OPD (or direct code pointer) at opd_ea into CTR/r2 and dispatch. */
extern "C" void ps3_call_opd(ppu_context* ctx, uint32_t opd_ea)
{
    uint32_t code = 0, toc = 0;
    uint32_t saved_toc = (uint32_t)ctx->gpr[2];
    ppu_opd_resolve(opd_ea, &code, &toc);
    if (code == 0x00171244u || code == 0x0032109Cu || opd_ea == 0x00522E70u ||
        opd_ea == 0x00534838u ||
        /* Micro-ctor schedule root (A1 climb 2026-07-22): OPD 0x534CB8 → 32854C */
        code == 0x0032854Cu || code == 0x00328B08u || code == 0x00329490u ||
        opd_ea == 0x00534CB8u || opd_ea == 0x00534CC0u) {
        static int n = 0;
        if (n++ < 64)
            fprintf(stderr, "[OPD-ICG] #%d opd=0x%08X code=0x%08X toc=0x%08X lr=0x%08X\n",
                    n, opd_ea, code, toc, (uint32_t)ctx->lr);
    }
    if (toc != 0)
        ctx->gpr[2] = toc;
    else
        ctx->gpr[2] = saved_toc;
    ctx->ctr = code;
    ps3_indirect_call(ctx);
}

/* ---------------------------------------------------------------------------
 * Post-WAD type-map unlock (faithful force of the real guest path).
 *
 * Evidence: full R_PermA completes (peak rem ≥ 0x1000000 then rem=0) with
 * SHGX as 48-byte catalog stubs and nested FIN = ELF blr. ICGLdr is
 * registered (type 0xF85F9B1E → OPD 0x534838) but func_00171244 (OPD
 * 0x522E70 / vt@0x5130B8+8) is never invoked — TYMAP-171=0, LDRSH=0.
 *
 * This helper logs that gate, locates the type-map object installed by
 * ICG-CTOR at component+0xDC, builds a minimal guest stream whose first
 * type tag is the registered ICGLdr type, and calls the real OPD 0x522E70
 * (func_00171244). That is the same path the game would take for a
 * component stream carrying type 0xF85F9B1E.
 * -----------------------------------------------------------------------*/
/* Guest BATCH (func_0014B1F0) already receives the ICG component and a stream
 * pointer and never vcalls typemap+8. This is that missing edge: same OPD the
 * walk uses (0x522E70), with the caller's real pointers — no synthetic payload,
 * not PS3_GATE_FORCE. One-shot. */
extern "C" void ps3_try_natural_icgldr_walk(ppu_context* ctx, uint32_t component,
                                           uint32_t stream_or_buf)
{
    static int s_done = 0;
    if (s_done || !ctx || !component)
        return;

    uint32_t tm = vm_read32(component + 0xDCu);
    uint32_t vt = tm ? vm_read32(tm) : 0;
    uint32_t s = stream_or_buf;
    uint32_t cur = 0, end = 0, buf = 0, w0 = 0;
    if (s >= 0x10000u && s < 0x4F000000u) {
        cur = vm_read32(s + 0x4u);
        end = vm_read32(s + 0x8u);
        buf = vm_read32(s + 0x10u);
        w0 = vm_read32(s);
    }
    int is_stream = (end > cur && buf >= 0x10000u && buf < 0x4F000000u &&
                     (end - cur) < 0x800000u);
    fprintf(stderr,
            "[TYMAP-WALK] comp=0x%08X tm=0x%08X vt=0x%08X s=0x%08X "
            "w0=0x%08X cur=0x%X end=0x%X buf=0x%08X stream=%d\n",
            component, tm, vt, s, w0, cur, end, buf, is_stream);
    fflush(stderr);

    if (!tm) {
        fprintf(stderr, "[TYMAP-WALK] skip: no typemap at component+0xDC\n");
        fflush(stderr);
        return;
    }

    uint32_t walk_stream = 0;
    if (is_stream) {
        walk_stream = s;
    } else if (w0 == 0xF85F9B1Eu) {
        /* r4 is the payload, not a stream object — wrap without inventing bytes. */
        uint32_t sp = (uint32_t)ctx->gpr[1];
        if (sp < 0x2000u)
            return;
        uint32_t obj = sp - 0x1000u;
        vm_write32(obj + 0x0, 0);
        vm_write32(obj + 0x4, 0);
        vm_write32(obj + 0x8, 8); /* type + u16 size, at least */
        vm_write32(obj + 0xC, 0);
        vm_write32(obj + 0x10, s);
        vm_write32(obj + 0x14, 0);
        vm_write32(obj + 0x18, 0);
        walk_stream = obj;
        fprintf(stderr, "[TYMAP-WALK] wrap payload s=0x%08X -> obj=0x%08X\n",
                s, obj);
        fflush(stderr);
    } else {
        fprintf(stderr, "[TYMAP-WALK] skip: r4 is not a stream object and w0!=F85F\n");
        fflush(stderr);
        return;
    }

    s_done = 1;
    uint64_t saved_r3 = ctx->gpr[3];
    uint64_t saved_r4 = ctx->gpr[4];
    uint64_t saved_r5 = ctx->gpr[5];
    ctx->gpr[3] = tm;
    ctx->gpr[4] = walk_stream;
    ctx->gpr[5] = 0;
    fprintf(stderr, "[TYMAP-WALK] call OPD 0x522E70 tm=0x%08X stream=0x%08X\n",
            tm, walk_stream);
    fflush(stderr);
    ps3_call_opd(ctx, 0x00522E70u);
    fprintf(stderr, "[TYMAP-WALK] returned r3=0x%08X\n", (uint32_t)ctx->gpr[3]);
    fflush(stderr);
    ctx->gpr[3] = saved_r3;
    ctx->gpr[4] = saved_r4;
    ctx->gpr[5] = saved_r5;
}

extern "C" void ps3_force_post_wad_icgldr(ppu_context* ctx)
{
    static int s_done = 0;
    static int s_fail_logs = 0;
    if (!ctx) return;
    if (!g_ps3_rperma_full) return;
    if (s_done) return;

    uint32_t toc = (uint32_t)ctx->gpr[2];
    if (!toc) {
        if (s_fail_logs++ < 8) {
            fprintf(stderr, "[GATE-FORCE] wait: TOC(r2)=0\n");
            fflush(stderr);
        }
        return;
    }
    uint32_t base = vm_read32(toc + (uint32_t)(-0x2584));
    if (!base) {
        if (s_fail_logs++ < 8) {
            fprintf(stderr, "[GATE-FORCE] wait: TOC-0x2584 base=0 toc=0x%08X\n", toc);
            fflush(stderr);
        }
        return;
    }
    uint32_t comp_slot = base + 0x130000u + 0x4980u;
    uint32_t component = vm_read32(comp_slot);
    uint32_t typemap = component ? vm_read32(component + 0xDC) : 0;
    uint32_t vt = typemap ? vm_read32(typemap + 0) : 0;

    /* Fallback: ICG-CTOR installs component at known live addr when slot empty. */
    if (!typemap) {
        /* Scan a few known component roots from prior smoke (ICG-CTOR r3). */
        static const uint32_t k_try[] = { 0x4306ADF0u, 0 };
        for (int i = 0; k_try[i]; i++) {
            uint32_t c = k_try[i];
            uint32_t tm = vm_read32(c + 0xDC);
            uint32_t tv = tm ? vm_read32(tm + 0) : 0;
            if (tm && (tv == 0x005130B8u || tv)) {
                component = c;
                typemap = tm;
                vt = tv;
                fprintf(stderr, "[GATE-FORCE] fallback component=0x%08X typemap=0x%08X\n",
                        component, typemap);
                fflush(stderr);
                break;
            }
        }
    }

    if (!typemap) {
        if (s_fail_logs++ < 12) {
            fprintf(stderr,
                    "[GATE-FORCE] wait: no typemap base=0x%08X slot=0x%08X comp=0x%08X\n",
                    base, comp_slot, component);
            fflush(stderr);
        }
        return;
    }

    /* Commit one-shot only once we will actually call the OPD. */
    s_done = 1;
    fprintf(stderr,
            "[GATE-FORCE] base=0x%08X component=0x%08X typemap=0x%08X vt=0x%08X\n",
            base, component, typemap, vt);
    fflush(stderr);

    if (vt != 0x005130B8u) {
        fprintf(stderr, "[GATE-FORCE] warn: vt!=0x5130B8 (got 0x%08X); still trying OPD 0x522E70\n", vt);
        fflush(stderr);
    }

    /* Build synthetic stream FAR below SP. Nested frames (171244 0xC0 +
     * 1856A8 0xC0 + deeper) clobber [SP-0x200, SP); force6 proved that a
     * stream at SP-0x100 is overwritten and type_tag becomes garbage
     * (0x004003EC instead of 0xF85F9B1E).
     * Layout matches 1856A8:
     *   +0x0 ops (unused when no refill), +0x4 cur, +0x8 end,
     *   +0x10 buffer base, +0x18 counter.
     * Payload: BE type 0xF85F9B1E, u16 size, optional BE tag. */
    uint32_t sp = (uint32_t)ctx->gpr[1];
    if (sp < 0x2000u) {
        fprintf(stderr, "[GATE-FORCE] fail: SP too low 0x%08X (will not retry)\n", sp);
        fflush(stderr);
        return;
    }
    /* Keep stream/data out of any nested stack frame range. */
    uint32_t stream_obj = sp - 0x1000u;
    uint32_t data_buf   = sp - 0x0F00u;

    /* Minimal map-level request only (type + size=0). A non-zero synthetic
     * ICGLdr payload (tag 0x283F6879) was proven to reach LDRSH recognized=1
     * but then spins CCPLdrShaderDefaultShader without real EFCT bytes.
     * Real shader microcode lives in EBOOT gzip (HOSTRES), not in WAD SHGX
     * stubs — do not fake an empty ICGLdr body here. */
    vm_write32(data_buf + 0x0, 0xF85F9B1Eu);
    vm_write16(data_buf + 0x4, 0x0000u);

    vm_write32(stream_obj + 0x0,  0);          /* ops: no refill needed */
    vm_write32(stream_obj + 0x4,  0);          /* cur */
    vm_write32(stream_obj + 0x8,  6);          /* end = type(4)+size(2) */
    vm_write32(stream_obj + 0xC,  0);
    vm_write32(stream_obj + 0x10, data_buf);   /* buffer */
    vm_write32(stream_obj + 0x14, 0);
    vm_write32(stream_obj + 0x18, 0);

    fprintf(stderr,
            "[GATE-FORCE] stream setup stream=0x%08X data=0x%08X type@data=0x%08X\n",
            stream_obj, data_buf, vm_read32(data_buf));
    fflush(stderr);

    fprintf(stderr,
            "[GATE-FORCE] calling OPD 0x522E70 (171244) this=0x%08X stream=0x%08X data=0x%08X\n",
            typemap, stream_obj, data_buf);
    fflush(stderr);

    uint64_t saved_r3 = ctx->gpr[3];
    uint64_t saved_r4 = ctx->gpr[4];
    uint64_t saved_r5 = ctx->gpr[5];
    uint64_t saved_r1 = ctx->gpr[1];
    uint64_t saved_r2 = ctx->gpr[2];
    ctx->gpr[3] = typemap;
    ctx->gpr[4] = stream_obj;
    ctx->gpr[5] = 0;
    ps3_call_opd(ctx, 0x00522E70u);
    ctx->gpr[3] = saved_r3;
    ctx->gpr[4] = saved_r4;
    ctx->gpr[5] = saved_r5;
    ctx->gpr[1] = saved_r1;
    ctx->gpr[2] = saved_r2;

    fprintf(stderr, "[GATE-FORCE] returned from 171244 path r3=0x%08X\n",
            (uint32_t)ctx->gpr[3]);
    fflush(stderr);
}

/* Run from an entry OPD: set up r1 (stack) + r2 (TOC) and dispatch the entry
 * code address. Returns 0 if it ran, -1 if the entry function isn't registered. */
#ifndef _WIN32
/* PS3_WATCH_OPD=1 (diag, OFF): nobody should write the vtables/.opd area
 * (0x510420..0x539178: C++ vtables + function descriptors) after load. Measured
 * 2026-09-22 after the post-Colossus cutscene: a virtual call through the type-1
 * script object read code 0x80029F47 from descriptor 0x51A2F0, whose ELF value is
 * 0x00029AF0 -- and the word was intact again when read later. This makes the
 * whole 16 KB host pages inside that range read-only: the first write from each
 * host PC is logged with its lifted function (= the guest writer), the page is
 * opened for the write and re-protected by a thread every 1 ms, which also diffs
 * the range against the load-time copy and logs every changed word (old -> new).
 * Diagnostic only: nothing is restored or dropped. */
#include <signal.h>
#include <sys/mman.h>
#include <sys/ucontext.h>
static uintptr_t s_opd_lo, s_opd_hi;               /* host range, page aligned */
static uint32_t  s_opd_ea_lo, s_opd_ea_hi;         /* guest range covered */
static uint8_t*  s_opd_snap;
static struct sigaction s_opd_old_segv, s_opd_old_bus;
static volatile unsigned s_opd_hits;
static int s_opd_diff_only;
static void opd_fault(int sig, siginfo_t* si, void* uc_)
{
    const uintptr_t fa = (uintptr_t)si->si_addr;
    if (s_opd_lo && fa >= s_opd_lo && fa < s_opd_hi) {
        const size_t pg = (size_t)getpagesize();
        const uintptr_t page = fa & ~(uintptr_t)(pg - 1);
        ucontext_t* uc = (ucontext_t*)uc_;
        void* pc = (void*)uc->uc_mcontext->__ss.__pc;
        void* lr = (void*)uc->uc_mcontext->__ss.__lr;
        static void* seen[64]; static int nseen;
        int known = 0;
        for (int i = 0; i < nseen; i++) if (seen[i] == pc) { known = 1; break; }
        if (!known && nseen < 64) {
            seen[nseen++] = pc;
            Dl_info a, b; const char* s0 = "?"; const char* s1 = "?"; long o0 = 0, o1 = 0;
            if (dladdr(pc, &a) && a.dli_sname) { s0 = a.dli_sname; o0 = (long)((char*)pc - (char*)a.dli_saddr); }
            if (dladdr(lr, &b) && b.dli_sname) { s1 = b.dli_sname; o1 = (long)((char*)lr - (char*)b.dli_saddr); }
            char line[512];
            int n = snprintf(line, sizeof line, "[WATCHOPD] write ea=0x%08X pc=%s+0x%lX lr=%s+0x%lX\n",
                             (unsigned)(fa - (uintptr_t)vm_base), s0, o0, s1, o1);
            if (n > 0) { ssize_t w = write(2, line, (size_t)n); (void)w; }
        }
        s_opd_hits++;
        mprotect((void*)page, pg, PROT_READ | PROT_WRITE);
        return;
    }
    struct sigaction* o = (sig == SIGBUS) ? &s_opd_old_bus : &s_opd_old_segv;
    if (o->sa_flags & SA_SIGINFO) { if (o->sa_sigaction) { o->sa_sigaction(sig, si, uc_); return; } }
    else if (o->sa_handler != SIG_DFL && o->sa_handler != SIG_IGN) { o->sa_handler(sig); return; }
    signal(sig, SIG_DFL); raise(sig);
}
static void* opd_rearm_thread(void*)
{
    const size_t len = s_opd_ea_hi - s_opd_ea_lo;
    unsigned logged = 0;
    /* The diff walks the whole range: 1 ms for the default 160 KB, 20 ms for
     * a multi-MB range. */
    const useconds_t tick = len > (1u << 20) ? 20000 : 1000;
    for (;;) {
        usleep(tick);
        for (size_t off = 0; off + 4 <= len && logged < 400u; off += 4) {
            uint32_t cur, old;
            memcpy(&cur, vm_base + s_opd_ea_lo + off, 4);
            memcpy(&old, s_opd_snap + off, 4);
            if (cur == old) continue;
            logged++;
            { struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
              fprintf(stderr, "[WATCHOPD] changed ea=0x%08X 0x%08X -> 0x%08X (hits=%u t=%ld.%03ld)\n",
                      (unsigned)(s_opd_ea_lo + off), __builtin_bswap32(old), __builtin_bswap32(cur), s_opd_hits,
                      (long)ts.tv_sec, (long)(ts.tv_nsec / 1000000)); }
            fflush(stderr);
            memcpy(s_opd_snap + off, &cur, 4);   /* report each new value once */
        }
        if (!s_opd_diff_only) mprotect((void*)s_opd_lo, s_opd_hi - s_opd_lo, PROT_READ);
    }
    return 0;
}
static void ps3_watch_opd_arm(void)
{
    const char* e = getenv("PS3_WATCH_OPD");
    if (!e || (e[0] != '1' && e[0] != '2') || !vm_base) return;
    /* 2 = diff only: no mprotect, no handler. Writers that fault inside a
     * host syscall or a thread with its own SIGSEGV handler (SPU job
     * isolation) hang the protected mode; this one still says what changed
     * and when. */
    s_opd_diff_only = (e[0] == '2');
    const size_t pg = (size_t)getpagesize();
    /* PS3_WATCH_OPD_RANGE=lo:hi (hex) watches another guest range instead, e.g.
     * 0x10000:0x50C7E0 = the whole R-X segment 0 (text, rodata, embedded SPU ELFs),
     * which the console maps read-only. */
    uint32_t ea_lo = 0x510420u, ea_hi = 0x539178u;
    { const char* r = getenv("PS3_WATCH_OPD_RANGE");
      if (r && *r) { char* end = 0; unsigned long a = strtoul(r, &end, 16);
          if (end && *end == ':') { unsigned long b = strtoul(end + 1, 0, 16);
              if (b > a) { ea_lo = (uint32_t)a; ea_hi = (uint32_t)b; } } } }
    const uintptr_t lo = ((uintptr_t)vm_base + ea_lo + pg - 1) & ~(uintptr_t)(pg - 1);
    const uintptr_t hi = ((uintptr_t)vm_base + ea_hi) & ~(uintptr_t)(pg - 1);
    if (hi <= lo) return;
    s_opd_lo = lo; s_opd_hi = hi;
    s_opd_ea_lo = (uint32_t)(lo - (uintptr_t)vm_base);
    s_opd_ea_hi = (uint32_t)(hi - (uintptr_t)vm_base);
    s_opd_snap = (uint8_t*)malloc(s_opd_ea_hi - s_opd_ea_lo);
    memcpy(s_opd_snap, vm_base + s_opd_ea_lo, s_opd_ea_hi - s_opd_ea_lo);
    if (!s_opd_diff_only) {
        struct sigaction sa; memset(&sa, 0, sizeof sa);
        sa.sa_sigaction = opd_fault; sa.sa_flags = SA_SIGINFO; sigemptyset(&sa.sa_mask);
        sigaction(SIGSEGV, &sa, &s_opd_old_segv); sigaction(SIGBUS, &sa, &s_opd_old_bus);
        mprotect((void*)lo, hi - lo, PROT_READ);
    }
    pthread_t t; pthread_create(&t, 0, opd_rearm_thread, 0); pthread_detach(t);
    fprintf(stderr, "[WATCHOPD] armed: guest 0x%08X..0x%08X read-only (page %zu)\n",
            s_opd_ea_lo, s_opd_ea_hi, pg);
}
#else
static void ps3_watch_opd_arm(void) {}
#endif

extern "C" int ppu_run(uint32_t entry_opd, uint32_t stack_top)
{
    ppu_vm_hot_gates_init();   /* E467: portoes do caminho quente lidos UMA vez */
    ps3_watch_opd_arm();
    uint32_t code = 0, toc = 0;
    ppu_opd_resolve(entry_opd, &code, &toc);
    ppu_fn fn = ppu_lookup(code);
    if (!fn) { fprintf(stderr, "[ppu] entry code 0x%08X not registered\n", code); return -1; }

    /* Task 2 (bringup-instrumentacao-fase0), requisito 6: liga a thread guest
     * corrente em TLS assim que a thread PPU principal comeca a preparar-se
     * para executar, para que <thr> deixe de ser "-" nos checkpoints TLS_INIT/
     * GUEST_ENTRY abaixo e em qualquer PS3_TRACE chamado desta thread daqui em
     * diante. A thread principal nunca passa por sys_ppu_thread_create (essa
     * atribui IDs 1..PPU_THREAD_MAX por slot -- ver sys_ppu_thread.c), por
     * isso usa-se aqui um sentinela fixo e fora dessa gama ('MAIN' em ASCII)
     * em vez de inventar um ID de slot que poderia colidir com uma thread
     * criada a seguir. */
    ps3_trace_set_thread(0x4D41494Eu /* 'MAIN' */);

    ppu_context ctx;
    memset(&ctx, 0, sizeof(ctx));
    ctx.gpr[1] = stack_top;   /* stack pointer */
    ctx.gpr[2] = toc;         /* TOC base (r2) */

    /* PS3 process-entry ABI (from upstream v0.7): CRT needs r7..r10 TLS + r12 page size. */
    ctx.gpr[7]  = 1;
    ctx.gpr[8]  = g_tls_vaddr;
    ctx.gpr[9]  = g_tls_filesz;
    ctx.gpr[10] = g_tls_memsz;
    ctx.gpr[12] = 0x100000;

    /* SCE process-entry ABI: lv2 pushes argc/argv/envp onto the top of the
     * initial stack and points r3/r4/r5 at them. GoW2's engine derives its
     * content base directory from argv[0] (dirname), then mounts
     * "<base>/gow2.psarc" -- with no argv the base is an empty string, the
     * mount object never gets created, and the game runs entirely without
     * I/O (no wads, no shaders, no movies). argv[0] is the standard disc
     * path; extra args come from PS3_ARGV (defaults to "-g", the contents
     * of the title's argv.txt). */
    {
        const char* argv_strs[4];
        int argc = 1;
        argv_strs[0] = "/dev_bdvd/PS3_GAME/USRDIR/EBOOT.BIN";
        const char* extra = getenv("PS3_ARGV");
        if (!extra) extra = "-g";
        if (extra[0]) argv_strs[argc++] = extra;

        uint32_t sp = stack_top;
        uint32_t straddr[4];
        for (int i = 0; i < argc; i++) {
            uint32_t len = (uint32_t)strlen(argv_strs[i]) + 1;
            sp -= len;
            memcpy(vm_base + sp, argv_strs[i], len);
            straddr[i] = sp;
        }
        sp &= ~0xFu;
        sp -= 4; vm_write32(sp, 0);                    /* envp[0] = NULL */
        uint32_t envp = sp;
        sp -= 4; vm_write32(sp, 0);                    /* argv[argc] = NULL */
        for (int i = argc - 1; i >= 0; i--) { sp -= 4; vm_write32(sp, straddr[i]); }
        uint32_t argvp = sp;
        sp &= ~0xFu;
        sp -= 0x70;                                    /* initial frame */
        ctx.gpr[1] = sp;
        ctx.gpr[3] = (uint32_t)argc;
        ctx.gpr[4] = argvp;
        ctx.gpr[5] = envp;
        ctx.gpr[6] = 0;
        fprintf(stderr, "[ppu] entry args: argc=%d argv0=\"%s\"%s%s\n", argc,
                argv_strs[0], argc > 1 ? " " : "", argc > 1 ? argv_strs[1] : "");
    }

    /* Main-thread TLS: copy the PT_TLS template into the TLS image (zeroing the
     * BSS tail) and point r13 at TP. The CRT accesses thread-locals relative to
     * r13; without this they hit address ~0 and corrupt the boot. */
    if (g_tls_memsz && (PPU_TLS_IMG + g_tls_memsz < (ppu_vm_size ? ppu_vm_size : 0x11000000u))) {
        /* PPU_TLS_IMG sits above main memory, in address space that vm_init
         * only reserves. The bound checked above is the guest's logical VM
         * size, which says nothing about whether these pages are backed --
         * writing here without committing first faults (SIGBUS on macOS,
         * access violation on Windows). Commit a window that covers the image
         * and the thread pointer at +0x7000, with room for guest TLS accesses
         * on either side of r13. */
        if (vm_commit(PPU_TLS_IMG, PPU_TLS_WINDOW) == CELL_OK) {
            memcpy(vm_base + PPU_TLS_IMG, vm_base + g_tls_vaddr, g_tls_filesz);
            if (g_tls_memsz > g_tls_filesz)
                memset(vm_base + PPU_TLS_IMG + g_tls_filesz, 0, g_tls_memsz - g_tls_filesz);
            ctx.gpr[13] = PPU_TLS_TP;
            fprintf(stderr, "[ppu] TLS image 0x%08X (r13/TP=0x%08X)\n", PPU_TLS_IMG, PPU_TLS_TP);
            /* Task 2: TLS_INIT -- TLS guest inicializado (imagem copiada,
             * r13/TP apontado). */
            ps3_checkpoint_fire(PS3_CP_TLS_INIT, "ppu_run",
                               "tls_img=0x%08X tp=0x%08X", PPU_TLS_IMG, PPU_TLS_TP);
        } else {
            fprintf(stderr, "[ppu] WARNING: could not commit TLS window at 0x%08X; "
                            "running without guest TLS\n", PPU_TLS_IMG);
        }
    }
    fprintf(stderr, "[ppu] run: code 0x%08X, toc 0x%08X, sp 0x%08X\n", code, toc, stack_top);
    ppu_rsv_register(&ctx);   /* main thread participates in cross-thread reservation tracking */
    /* PS3_GIANT_HLE_ONLY: sem aquisicao na entrada -- o lock passa a ser dos
     * funis HLE (ps3_hle_call / lv2_syscall). */
    if (!ppu_giant_hle_only())
        ppu_giant_lock_acquire(); /* see the giant-lock comment above: serializes vs. worker PPU threads */
    /* Task 2: GUEST_ENTRY -- primeira instrucao guest do entry point, o
     * instante imediatamente antes de fn(&ctx) (o dispatch para o codigo
     * lifted do entry). */
    ps3_checkpoint_fire(PS3_CP_GUEST_ENTRY, "ppu_run",
                       "code=0x%08X toc=0x%08X sp=0x%08X", code, toc, stack_top);
    fn(&ctx);
    while (g_trampoline_fn) { void (*tf)(void*) = g_trampoline_fn; g_trampoline_fn = 0; tf(&ctx); }
    if (!ppu_giant_hle_only())
        ppu_giant_lock_release();
    return 0;
}
